const crumbLd=(c,p)=>JSON.stringify({"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[["Home","/"],...c].map((x,i)=>({"@type":"ListItem","position":i+1,"name":x[0],"item":SITE+(x[1]||p)}))});
const PAGES=[];
const QUEUE=[],SEARCH=[];
