function renderPage(p,{title,desc,body,cr=[],schema,noindex,ogImg='house3'}){
 const tail=enrich(p,title);if(tail){const k='<section style="padding-bottom:0"><div class="wrap"><div class="fcta';const i=body.lastIndexOf(k);body=i>0?body.slice(0,i)+tail+body.slice(i):body+tail}
 if(!noindex)SEARCH.push({u:p,t:title,d:desc});
 const pre=(body.match(/<img[^>]*fetchpriority="high"[^>]*>/)||[''])[0];const preSrc=(pre.match(/src="([^"]+)"/)||[])[1],preSet=(pre.match(/srcset="([^"]+)"/)||[])[1];const full=p==='/'?title:`${title} | MoveMatch`;
 const html=`<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(full)}</title><meta name="description" content="${esc(desc)}"><link rel="canonical" href="${SITE}${p}">
${noindex?'<meta name="robots" content="noindex">':''}
<meta property="og:type" content="website"><meta property="og:site_name" content="MoveMatch"><meta property="og:title" content="${esc(full)}"><meta property="og:description" content="${esc(desc)}"><meta property="og:url" content="${SITE}${p}"><meta property="og:image" content="${SITE}/og-image.png"><meta name="twitter:card" content="summary_large_image">
<meta name="theme-color" content="#102A43"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="icon" href="/favicon-32.png" sizes="32x32"><link rel="icon" href="/favicon-16.png" sizes="16x16"><link rel="apple-touch-icon" href="/apple-touch-icon.png"><link rel="manifest" href="/site.webmanifest">
${preSrc?`<link rel="preload" as="image" href="${preSrc.replace(/&amp;/g,'&')}" imagesrcset="${preSet}" imagesizes="100vw" fetchpriority="high">`:''}<link rel="preconnect" href="https://images.unsplash.com"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Manrope:wght@600;700;800&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
<link rel="stylesheet" href="/style.css?v=${V}">
${cr.length?`<script type="application/ld+json">${crumbLd(cr,p)}</script>`:''}${schema?`<script type="application/ld+json">${JSON.stringify(schema)}</script>`:''}
</head><body>${header(p)}<main id="main">${body}</main>${footer()}<script src="/app.js?v=${V}" defer></script></body></html>`;
 const dir=path.join(OUT,p);fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(path.join(dir,'index.html'),html);}

