page('/',{title:'MoveMatch — Compare Trusted Movers & Get Free Moving Quotes',desc:'Find trusted moving professionals, compare competitive quotes and make your next move easier, smarter and stress-free. Local, long-distance, commercial, packing and storage.',
schema:{"@context":"https://schema.org","@type":"WebSite","name":"MoveMatch","url":SITE,"potentialAction":{"@type":"SearchAction","target":SITE+"/movers/search/?q={q}","query-input":"required name=q"}},
body:`
<section class="hero" aria-labelledby="hT"><div class="hbg">${img('house3','Suburban American street with houses and trees',1800,true)}</div><div class="shade"></div><div class="shade2"></div>
<div class="wrap hero-g">
 <div>
  <p class="eyebrow st st1" style="color:var(--teal)">${ic('truck',16)} America's moving marketplace</p>
  <h1 id="hT" class="st st2">Your Next Move Starts With a <span class="hl">Better Match.</span></h1>
  <p class="lead st st3">Find trusted moving professionals, compare competitive quotes and make your next move easier, smarter and stress-free.</p>
  <ul class="tpoints st st4"><li><span class="tk">${ic('check',14,3.2).replace('currentColor','#102A43')}</span>Compare multiple moving providers</li><li><span class="tk">${ic('check',14,3.2).replace('currentColor','#102A43')}</span>Transparent estimates</li><li><span class="tk">${ic('check',14,3.2).replace('currentColor','#102A43')}</span>Verified provider checks</li></ul>
  <div class="hsvc st st5">${[['residential-moving','Residential'],['long-distance','Long-distance','/movers/long-distance/','map'],['office-moving','Office'],['packing','Packing'],['storage','Storage'],['piano-moving','Piano']].map(x=>{const s=SV[x[0]];return `<a href="${s?s.url:x[2]}">${ic(s?s.icon:x[3],16)}${x[1]}</a>`}).join('')}</div>
  <div class="hctas st st5"><a href="/get-quotes/" class="btn btn-p btn-lg">Compare Free Moving Quotes ${arr}</a><a href="/services/residential-moving/" class="btn btn-w btn-lg">Explore Moving Services</a></div>
 </div>
 <form class="qcard st st6" id="heroForm" action="/get-quotes/" novalidate aria-labelledby="qT">
  <h2 id="qT">Get your free moving quotes</h2><p class="sub" id="hsLbl" aria-live="polite">Step 1 of 2</p>
  <div class="qsteps" aria-hidden="true"><i class="on"></i><i></i></div>
  <div class="hstep fgrid">
   <div class="fld ac full"><label for="hFrom">Moving from <span class="req">*</span></label><div class="iw">${ic('pin',18)}<input id="hFrom" name="from" data-ac autocomplete="off" placeholder="City or ZIP code" required aria-describedby="hFromE"></div><div class="msg" id="hFromE">Enter a US city or 5-digit ZIP code.</div></div>
   <div class="fld ac full"><label for="hTo">Moving to <span class="req">*</span></label><div class="iw">${ic('pin',18)}<input id="hTo" name="to" data-ac autocomplete="off" placeholder="City or ZIP code" required aria-describedby="hToE"></div><div class="msg" id="hToE">Enter a US city or 5-digit ZIP code.</div></div>
   <div class="fld full"><label for="hDate">Moving date <span class="req">*</span></label><div class="iw">${ic('cal',18)}<input type="date" id="hDate" name="date" required></div><div class="msg">Choose a date from today onwards.</div></div>
  </div>
  <div class="hstep fgrid" hidden>
   <div class="fld full"><label for="hType">Move type</label><select id="hType" name="type"><option>Local</option><option>Long-distance</option><option>Interstate</option><option>International</option><option>Commercial</option></select></div>
   <div class="fld"><label for="hProp">Property type</label><select id="hProp" name="prop"><option>House</option><option selected>Apartment</option><option>Condo</option><option>Studio</option><option>Office</option><option>Storage unit</option></select></div>
   <div class="fld"><label for="hSize">Home size</label><select id="hSize" name="rooms"><option>Studio</option><option selected>1 bedroom</option><option>2 bedrooms</option><option>3 bedrooms</option><option>4+ bedrooms</option><option>Not applicable</option></select></div>
   <button type="button" class="btn btn-g full" id="hBack" style="justify-self:start;min-height:40px">← Back</button>
  </div>
  <button type="submit" id="hSub" class="btn btn-p btn-lg" style="width:100%;margin-top:16px">Continue ${arr}</button>
  <p class="free">${ic('lock',14)} Free to request. No obligation.</p>
 </form>
</div>
<div class="road" aria-hidden="true"><div class="trees">${[90,70,100,80,95,75,88].map((h,i)=>tree(h,i%2?'#2f6b4f':'#3d7d5c')).join('')}</div><div class="curb"></div><div class="asph"></div><div class="lane"></div>${vanSvg}</div>
</section>

<div class="trust" aria-label="How we build trust"><div class="wrap trust-g">
 ${[['shield','Separate verification checks','Identity, business, licence and insurance shown individually.'],['list','Transparent estimates','Estimate type, inclusions and extra charges disclosed.'],['lock','Data protection','Details shared only with providers you choose.'],['headset','Human support','Claims, complaints and disputes reviewed by people.']].map(t=>`<div class="ti rv-in"><div class="ic">${ic(t[0])}</div><div><b>${t[1]}</b><span>${t[2]}</span></div></div>`).join('')}
</div></div>

<section class="alt"><div class="wrap"><div class="sh-row"><div class="sh"><p class="eyebrow">One platform. Every way to move.</p><h2 class="h2">How would you like to move?</h2><p class="lead">Choose how much you want to do yourself — then compare options for the same move.</p></div><a href="/moving-methods/" class="btn btn-s">Compare all methods ${arr}</a></div>${methodCards}</div></section>
<section id="services"><div class="wrap">
 <div class="sh-row"><div class="sh"><p class="eyebrow">Moving services</p><h2 class="h2">Every kind of move, one place to compare</h2><p class="lead">Choose the service that fits your move. Each one has its own guide and connects you with providers who offer it.</p></div><a href="/get-quotes/" class="btn btn-o">Not sure? Start a quote ${arr}</a></div>
 <div class="grid g4">${['residential-moving','commercial-moving','packing','storage','piano-moving','vehicle-transport','junk-removal','labor-only'].map((s,i)=>svcCard(SV[s],i)).join('')}</div>
</div></section>

<section id="how" class="alt"><div class="wrap">
 <div class="sh c"><p class="eyebrow">How MoveMatch works</p><h2 class="h2">From first question to moving day</h2><p class="lead">A clear, four-step journey — you stay in control at every stage.</p></div>
 <div class="tl" id="tl"><div class="tl-line"><i></i></div>
  <div class="tstep"><div class="tnum">1</div><div class="tcard"><div class="tvis"><div class="vform"><i class="f"></i><i class="f" style="animation-delay:.4s"></i><i class="f" style="animation-delay:.8s;width:70%"></i><i class="b"></i></div></div><div class="tb"><h3>Tell us about your move</h3><ul><li>Enter origin and destination</li><li>Select your date</li><li>Choose property type</li><li>Add inventory & extra services</li></ul></div></div></div>
  <div class="tstep"><div class="tnum">2</div><div class="tcard"><div class="tvis"><div class="vq">Provider estimate</div><div class="vq">Provider estimate</div><div class="vq">Provider estimate</div></div><div class="tb"><h3>Receive provider responses</h3><ul><li>We match relevant providers</li><li>Providers review your request</li><li>They submit estimates</li><li>You're notified as they arrive</li></ul></div></div></div>
  <div class="tstep"><div class="tnum">3</div><div class="tcard"><div class="tvis"><div class="vcmp"><i style="--h:60px"></i><i style="--h:84px"></i><i style="--h:48px"></i></div></div><div class="tb"><h3>Compare your options</h3><ul><li>Compare estimates side by side</li><li>Review what's included</li><li>Understand extra charges</li><li>Check verification</li></ul></div></div></div>
  <div class="tstep"><div class="tnum">4</div><div class="tcard"><div class="tvis">${img('unload2','Movers unloading furniture from a truck at a new home',500)}</div><div class="tb"><h3>Book & manage your move</h3><ul><li>Select your provider</li><li>Review the agreement</li><li>Confirm date & pay deposit</li><li>Track progress & documents</li></ul></div></div></div>
 </div>
 <div style="text-align:center;margin-top:40px"><a href="/how-it-works/" class="btn btn-s">See the full process ${arr}</a></div>
</div></section>

<section id="providers"><div class="wrap">
 <div class="sh-row"><div class="sh"><p class="eyebrow">Featured moving companies</p><h2 class="h2">Browse moving providers</h2><p class="lead">Filter by move type, tick up to three to compare, and request quotes directly.</p></div><a href="/movers/search/" class="btn btn-o">Search all movers ${arr}</a></div>
 ${provSection()}
</div></section>

<section id="calculator" class="alt"><div class="wrap">
 <div class="sh"><p class="eyebrow">Moving cost calculator</p><h2 class="h2">See an indicative cost range</h2><p class="lead">Adjust the details to see how each factor affects price. This is a guide, not a quote.</p></div>${calcBlock}
</div></section>

<section id="compare"><div class="wrap">
 <div class="sh"><p class="eyebrow">Compare moving providers</p><h2 class="h2">Side-by-side, apples to apples</h2><p class="lead">Select providers with “Compare” above. Until you do, we show three sample profiles. Scroll sideways on mobile.</p></div>${cmpTable}
</div></section>

${splitSvc('Residential moving','Home moves handled with care','Houses, apartments, condos and studios — plus student, senior, military and family relocations.','unload2',['house-moving','apartment-moving','condo-moving','student-moving','senior-moving','family-relocation'],false,false)}
${splitSvc('Commercial moving','Business moves with minimal downtime','Offices, retail stores, warehouses and corporate sites — planned around your operations.','office2',['office-moving','corporate-relocation','retail-moving','warehouse-moving','industrial-moving','medical-office-moving'],true,true)}
${splitSvc('Specialist moving','The items that need an expert','Pianos, antiques, fine art, safes, pool tables and vehicles — moved by trained specialists.','piano',['piano-moving','antique-moving','fine-art-moving','safe-moving','pool-table-moving','vehicle-transport'],false,false)}

<section class="alt"><div class="wrap">
 <div class="sh"><p class="eyebrow">Additional moving services</p><h2 class="h2">Everything around the move</h2></div>
 <div class="grid g4">${['packing','unpacking','storage','junk-removal','moving-cleaning','furniture-assembly','loading','unloading'].map((s,i)=>svcCard(SV[s],i)).join('')}</div>
</div></section>

<section id="cities"><div class="wrap">
 <div class="sh-row"><div class="sh"><p class="eyebrow">Popular moving destinations</p><h2 class="h2">Moving to or from a major city?</h2><p class="lead">Provider availability is shown per city once approved providers serve that area.</p></div><a href="/city-guides/" class="btn btn-o">All city guides ${arr}</a></div>
 <div class="grid g4">${CITIES.map((c,i)=>`<a href="/get-quotes/" data-seed='{"to":"${c[0]}, ${c[1]}"}' class="card city rv-in" style="transition-delay:${(i%4)*50}ms"><div class="ph">${img(c[2],'',500)}</div><div class="cb"><div><b>${c[0]}</b><small>${c[1]} · Providers onboarding</small></div><span class="ar">${ic('arrow',18)}</span></div></a>`).join('')}</div>
</div></section>

<section class="alt"><div class="wrap">
 <div class="sh"><p class="eyebrow">Moving process explained</p><h2 class="h2">Which type of move is right for you?</h2></div>
 <div class="tabs" role="tablist" aria-label="Move types">${['Full-service','Moving containers','Truck rental','Labor-only','Storage','Brokers vs carriers'].map((t,i)=>`<button class="tab" role="tab" id="t${i}" aria-selected="${!i}" aria-controls="tp${i}" tabindex="${i?-1:0}">${t}</button>`).join('')}</div>
 ${[['Full-service','Movers pack, load, transport and unload everything for you.',['Least effort for you','Crew handles heavy and fragile items','Packing and assembly available'],['Highest cost option','Scheduling depends on crew availability'],'unload1'],
   ['Moving containers','A container is dropped off; you load it, the company transports it.',['Flexible loading time','Often cheaper than full-service','Doubles as storage'],['You do the loading','Needs driveway or street space'],'boxesRoad'],
   ['Truck rental','You rent a truck and do the move yourself.',['Usually the lowest price','Full control of timing'],['You drive and lift','Fuel, tolls and insurance extra'],'uhaul'],
   ['Labor-only','Hire movers to load or unload a truck or container you arrange.',['Pairs with rental or containers','Pay only for the help you need'],['You arrange transport','Usually hourly with minimums'],'carry'],
   ['Storage','Hold belongings between moves or long-term.',['Bridges move-out and move-in dates','Climate-controlled options'],['Monthly fees add up','Access hours may be limited'],'wh3'],
   ['Brokers vs carriers','A carrier owns trucks and performs the move. A broker arranges the move with a carrier.',['Brokers can find availability fast','Carriers offer direct accountability','MoveMatch labels each provider type'],['A broker does not move your goods itself','Always check who performs the move'],'semi']].map((e,i)=>`<div class="tpanel" role="tabpanel" id="tp${i}" aria-labelledby="t${i}" ${i?'hidden':''}><div><h3 style="font-size:28px;margin-bottom:10px">${e[0]}</h3><p class="lead">${e[1]}</p><div class="pc"><div class="pro"><h4>Advantages</h4><ul>${e[2].map(x=>`<li>${x}</li>`).join('')}</ul></div><div class="con"><h4>Consider</h4><ul>${e[3].map(x=>`<li>${x}</li>`).join('')}</ul></div></div></div><div class="pframe">${img(e[4],e[0],700)}</div></div>`).join('')}
</div></section>

<section class="dark"><div class="wrap">
 <div class="sh-row"><div class="sh"><p class="eyebrow">For moving companies</p><h2 class="h2">Moving company benefits</h2><p class="lead">Receive qualified requests, send itemised quotes and manage bookings and payments from one dashboard.</p></div><a href="/for-movers/register/" class="btn btn-p btn-lg">Apply as a Mover ${arr}</a></div>
 <div class="ben">${[['users','Qualified leads','Requests matched to your area, services and capacity.'],['shield','Transparent verification','Each check shown separately on your profile.'],['doc','Itemised quotes','Send estimates with revision history.'],['cal','Booking management','Dates, crews and customer messages.'],['wallet','Payments','Deposits, receipts and refunds in one place.'],['chart','Analytics','Response rates and conversion insight.']].map((b,i)=>`<div class="rv-in" style="transition-delay:${(i%3)*80}ms"><div class="icb">${ic(b[0])}</div><h3>${b[1]}</h3><p>${b[2]}</p></div>`).join('')}</div>
</div></section>

<section><div class="wrap">
 <div class="sh"><p class="eyebrow">Customer stories</p><h2 class="h2">What a good move feels like</h2></div>
 <div class="rv-wrap" data-carousel><div class="rv-track">${STORIES.map(s=>`<figure class="card rv"><div class="stars" aria-label="5 out of 5">★★★★★</div><blockquote>“${s[2]}”</blockquote><figcaption class="who"><span class="av" aria-hidden="true">${s[0][0]}</span><span><b>${s[0]}</b>${s[1]}</span></figcaption></figure>`).join('')}</div></div>
 <div class="rvnav"><button class="ibtn rvP" aria-label="Previous story">‹</button><div class="pgs"></div><button class="ibtn rvN" aria-label="Next story">›</button></div>
 <p class="disc">Illustrative examples for design preview. Only verified reviews from completed bookings will be published.</p>
</div></section>

<section class="alt"><div class="wrap">
 <div class="sh-row"><div class="sh"><p class="eyebrow">Moving resources</p><h2 class="h2">Tools to plan a smoother move</h2></div><a href="/moving-guides/" class="btn btn-o">All guides ${arr}</a></div>
 <div class="grid g3">${RES.map((r,i)=>`<a href="${r[0]}" class="card rcard rv-in" style="transition-delay:${(i%3)*70}ms"><div class="ph">${img(r[1],'',600)}</div><div class="rb"><small>${r[2]}</small><h3>${r[3]}</h3><p>${r[4]}</p><span class="link">Open ${arr}</span></div></a>`).join('')}</div>
</div></section>

<section><div class="wrap">
 <div class="sh-row"><div class="sh"><p class="eyebrow">Moving tips & checklist</p><h2 class="h2">Your moving timeline at a glance</h2></div><a href="/moving-checklists/" class="btn btn-s">Interactive checklist ${arr}</a></div>
 <div class="ck">${[['8 weeks',['Set budget','Research movers','Declutter']],['6 weeks',['Request quotes','Order supplies','Measure furniture']],['4 weeks',['Book mover','Change address','Notify utilities']],['2 weeks',['Pack non-essentials','Confirm access','Arrange pet care']],['1 week',['Pack rooms','Essentials bag','Defrost freezer']],['Moving day',['Walk-through','Check inventory','Sign paperwork']],['After',['Unpack priorities','Check for damage','Leave a review']]].map((c,i)=>`<div class="ckc rv-in${i===5?' now':''}" style="transition-delay:${i*60}ms"><b>${c[0]}</b><ul>${c[1].map(x=>`<li>${x}</li>`).join('')}</ul></div>`).join('')}</div>
</div></section>

<section class="alt" id="faq"><div class="wrap faqw"><div class="sh c"><p class="eyebrow">FAQ</p><h2 class="h2">Frequently asked questions</h2></div>${faqBlock(FAQS,true)}<p style="text-align:center;margin-top:20px"><a class="link" href="/faqs/">See all FAQs ${arr}</a></p></div></section>
${ctaBlock()}`});

/* ============ SERVICES ============ */
SERVICES.forEach(s=>{const rel=SERVICES.filter(x=>x.cat===s.cat&&x.slug!==s.slug).slice(0,3);
page(s.url,{title:`${s.name} — Compare Providers & Free Quotes`,desc:`${s.desc} Compare ${s.name.toLowerCase()} providers and get free quotes with MoveMatch.`,cr:[['Moving Services','/services/residential-moving/'],[s.name,s.url]],
 schema:{"@context":"https://schema.org","@type":"Service","name":s.name,"serviceType":s.name,"areaServed":"US","provider":{"@type":"Organization","name":"MoveMatch"}},
 body:phero([['Moving Services','/services/residential-moving/'],[s.name]],s.cat+' service',s.name,s.desc,s.im,`<div class="ctas st st3"><a href="/get-quotes/" class="btn btn-p btn-lg" data-seed='{"svc":"${s.name}"}'>Get ${s.name} Quotes ${arr}</a><a href="/tools/moving-cost-calculator/" class="btn btn-w btn-lg">Estimate cost</a></div>`)+
 `<section><div class="wrap cgrid"><article class="prose">
 <h2>What's included</h2><ul>${s.inc.map(x=>`<li>${x}</li>`).join('')}</ul>
 <div class="pframe rv-in">${img(s.im,s.name,1000)}</div>
 <h2>How ${s.name.toLowerCase()} is priced</h2><p>${s.price}</p><p>Every estimate on MoveMatch shows its type — binding, non-binding or not-to-exceed — and lists what's included and any extra charges before you book.</p>
 <h2>Tips from moving professionals</h2><ul>${s.tips.map(x=>`<li>${x}</li>`).join('')}</ul>
 <h2>How to book through MoveMatch</h2><ol class="tl-v"><li><i>1</i><div><b>Request quotes</b><span>Tell us about your move and select ${s.name.toLowerCase()}.</span></div></li><li><i>2</i><div><b>Compare providers</b><span>Review estimates, inclusions and verification.</span></div></li><li><i>3</i><div><b>Book and track</b><span>Confirm your date and follow progress.</span></div></li></ol>
 <h2>Frequently asked questions</h2>${faqBlock([[`How far ahead should I book ${s.name.toLowerCase()}?`,'Four to eight weeks is ideal, especially from May to September. Last-minute moves are possible but availability is more limited.'],['Is the estimate binding?','It depends on the provider. Each quote clearly states whether it is binding, non-binding or not-to-exceed.'],['Are the providers insured?','Insurance is one of the separate verification checks. Profiles show whether insurance has been verified.']])}
 </article><aside class="aside"><div class="card"><h3>Get ${s.name.toLowerCase()} quotes</h3><p class="help" style="margin:0 0 14px">Free, no obligation.</p><a class="btn btn-p" style="width:100%" href="/get-quotes/" data-seed='{"svc":"${s.name}"}'>Start my request</a></div>
 <div class="card"><h3>Related services</h3>${rel.map(r=>`<a class="al" href="${r.url}">${r.name}<span>›</span></a>`).join('')}</div>
 <div class="card"><h3>Helpful tools</h3><a class="al" href="/tools/moving-cost-calculator/">Cost calculator<span>›</span></a><a class="al" href="/tools/packing-calculator/">Packing calculator<span>›</span></a><a class="al" href="/moving-checklists/">Moving checklist<span>›</span></a></div></aside></div></section>
 <section class="alt"><div class="wrap"><div class="sh"><p class="eyebrow">More ${s.cat.toLowerCase()} services</p><h2 class="h2">You might also need</h2></div><div class="grid g3">${rel.map(svcCard).join('')}</div></div></section>${ctaBlock()}`});});

/* ============ MOVERS ============ */
Object.entries(MOVERS).forEach(([slug,m])=>{const p=`/movers/${slug}/`;
 const extra=slug==='near-me'?`<form class="card" style="margin-bottom:26px;display:flex;gap:12px;flex-wrap:wrap;align-items:flex-end" onsubmit="event.preventDefault();var v=document.getElementById('nmZip');var ok=/^\\d{5}$/.test(v.value)||v.value.length>2;v.closest('.fld').classList.toggle('bad',!ok);if(ok){document.getElementById('pSearch').value='';mmToast('Showing providers for '+v.value+' — more providers are onboarding in your area.','var(--info)')}"><div class="fld ac" style="flex:1;min-width:220px"><label for="nmZip">Your ZIP code or city</label><div class="iw">${ic('pin',18)}<input id="nmZip" data-ac placeholder="e.g. 60601 or Chicago, IL"></div><div class="msg">Enter a ZIP code or city.</div></div><button class="btn btn-s">Find movers</button></form>`:'';
 const intro={verified:`<div class="grid g4" style="margin-bottom:36px">${[['user','Identity verified','Owner identity confirmed with documents.'],['building','Business verified','Registration checked against public records.'],['doc','Licence verified','USDOT/MC numbers for interstate carriers.'],['shield','Insurance verified','Current certificate of insurance on file.']].map(x=>`<div class="card hov"><div class="icb">${ic(x[0])}</div><h3 style="font-size:17px">${x[1]}</h3><p class="help">${x[2]}</p></div>`).join('')}</div>`,compare:`<div id="compare" style="margin-bottom:40px"><h2 class="h2" style="font-size:28px">Your comparison</h2><p class="lead" style="margin-bottom:18px">Tick “Compare” on up to three providers below. Your selection is remembered.</p>${cmpTable}</div>`,featured:`<div class="notice info" style="margin-bottom:22px">${ic('star',20)}<div><b>Disclosure:</b> featured placement may be paid. It never changes a provider's ratings, verification or the order of search results.</div></div>`}[slug]||'';
 page(p,{title:`${m[0]} — Compare & Get Free Quotes`,desc:`${m[2]} Compare ${m[0].toLowerCase()} on MoveMatch and request free quotes.`,cr:[['Find Movers','/movers/search/'],[m[0],p]],
 body:phero([['Find Movers','/movers/search/'],[m[0]]],'Find movers',m[0],m[2],m[3],`<div class="ctas st st3"><a href="/get-quotes/" class="btn btn-p btn-lg">Get Free Quotes ${arr}</a><a href="/how-it-works/" class="btn btn-w btn-lg">How it works</a></div>`)+
 `<section><div class="wrap">${extra}${intro}${provSection(m[4])}</div></section>
 <section class="alt"><div class="wrap split"><div class="rv-in"><p class="eyebrow">Choosing ${m[0].toLowerCase()}</p><h2 class="h2">What to check before you book</h2><ul class="ulist">${['Which verification checks are complete','Whether the estimate is binding or non-binding','What is included — and what costs extra','Valuation and protection options','Who performs the move: carrier or broker'].map(x=>`<li><span class="tk">${tick}</span>${x}</li>`).join('')}</ul><a class="btn btn-s" href="/review-estimates/">Understand estimates ${arr}</a></div><div class="pframe rv-in">${img(m[3],m[0],800)}</div></div></section>${ctaBlock()}`});});

/* ============ QUOTE WIZARD ============ */
const steps=['Locations','Date','Property','Inventory','Packing & storage','Special items','Access','Extra services','Contact','Review'];
const radio=(name,opts,req)=>`<div class="choice" ${req?'data-req-radio':''} role="radiogroup">${opts.map((o,i)=>`<label><input type="radio" name="${name}" value="${o[0]}"${i===0&&!req?' checked':''}><span>${o[0]}</span>${o[1]?`<small>${o[1]}</small>`:''}</label>`).join('')}</div>`;
const INV=[['Sofa','Living room'],['Armchair','Living room'],['TV','Living room'],['Bed (queen/king)','Bedroom'],['Bed (twin/full)','Bedroom'],['Dresser','Bedroom'],['Wardrobe','Bedroom'],['Dining table','Kitchen'],['Dining chairs','Kitchen'],['Refrigerator','Appliances'],['Washer / dryer','Appliances'],['Desk','Office'],['Office chair','Office'],['Bookcase','Office'],['Boxes (small)','Boxes'],['Boxes (medium)','Boxes'],['Boxes (large)','Boxes'],['Bicycle','Other']];
page('/get-quotes/',{title:'Get Free Moving Quotes',desc:'Request free moving quotes in a few minutes. Tell us about your move and compare estimates from matched providers.',cr:[['Get Quotes','/get-quotes/']],
body:phero([['Get Quotes']],'Free moving quotes','Get your free moving quotes','Answer a few questions — it takes about 3 minutes. Your progress is saved automatically.','unload1')+
`<section style="padding-top:56px"><div class="wrap"><div class="wiz" id="wizard">
 <aside class="wside"><b style="font-family:var(--fh);font-size:18px">Your moving request</b><ol>${steps.map((s,i)=>`<li><i>${i+1}</i><span>${s}</span></li>`).join('')}</ol></aside>
 <div class="wmain"><div class="prog"><i id="wProg"></i></div><p class="help" id="wStep" aria-live="polite" style="margin:0 0 18px"></p>
 <form novalidate onsubmit="return false">
  <div class="ws"><h2>Where are you moving?</h2><div class="fgrid">
   <div class="fld ac full"><label for="wFrom">Moving from <span class="req">*</span></label><div class="iw">${ic('pin',18)}<input id="wFrom" name="from" data-ac required autocomplete="off" placeholder="City or ZIP code"></div><div class="msg">Enter a US city or 5-digit ZIP code.</div></div>
   <div class="fld ac full"><label for="wTo">Moving to <span class="req">*</span></label><div class="iw">${ic('pin',18)}<input id="wTo" name="to" data-ac required autocomplete="off" placeholder="City or ZIP code"></div><div class="msg">Enter a US city or 5-digit ZIP code.</div></div>
   <div class="fld full"><label for="wType">Move type</label><select id="wType" name="mtype"><option>Local</option><option>Long-distance</option><option>Interstate</option><option>International</option><option>Commercial</option></select></div></div></div>
  <div class="ws"><h2>When are you moving?</h2><div class="fgrid"><div class="fld"><label for="wDate">Moving date <span class="req">*</span></label><input type="date" id="wDate" name="date" required><div class="msg">Choose a date from today onwards.</div></div><div class="fld"><label for="wFlex">Date flexibility</label><select id="wFlex" name="flex"><option>Exact date</option><option>± 3 days</option><option>± 1 week</option><option>Flexible</option></select></div></div><p class="help">Flexible dates often mean better availability and prices.</p></div>
  <div class="ws"><h2>Tell us about the property</h2><div class="fld"><span class="flab">Property type</span>${radio('prop',[['House',''],['Apartment',''],['Condo',''],['Studio',''],['Office',''],['Storage unit','']])}</div><div class="fgrid"><div class="fld"><label for="wRooms">Bedrooms / rooms</label><select id="wRooms" name="rooms"><option>1</option><option selected>2</option><option>3</option><option>4</option><option>5+</option></select></div><div class="fld"><label for="wSqft">Approx. size (sq ft)</label><input id="wSqft" name="sqft" inputmode="numeric" placeholder="Optional"></div></div></div>
  <div class="ws"><h2>What are you moving?</h2><p class="help" style="margin:0">Add large items and boxes. You can refine this with your provider later.</p><div class="inv">${INV.map(x=>`<div class="it" data-k="${x[0]}"><span>${x[0]}<br><small class="help" style="margin:0">${x[1]}</small></span><div class="qty"><button type="button" data-d="-1" aria-label="Fewer ${x[0]}">−</button><output aria-live="polite">0</output><button type="button" data-d="1" aria-label="More ${x[0]}">+</button></div></div>`).join('')}</div><div class="fld"><label for="wNotes">Notes about items (fragile, disassembly needed…)</label><textarea id="wNotes" name="notes" rows="3"></textarea></div></div>
  <div class="ws"><h2>Packing and storage</h2><div class="fld"><span class="flab">Packing</span>${radio('packing',[['I\'ll pack myself','Lowest cost'],['Partial packing','Fragile items only'],['Full packing','Movers pack everything']])}</div><div class="fld"><span class="flab">Storage</span>${radio('storage',[['No storage',''],['Short-term','Under 3 months'],['Long-term','3+ months']])}</div></div>
  <div class="ws"><h2>Any specialty items?</h2><div class="fgrid">${['Piano','Pool table','Safe','Antiques','Fine art','Gym equipment','Hot tub','Vehicle'].map(x=>`<label class="chk"><input type="checkbox" name="special" value="${x}">${x}</label>`).join('')}</div></div>
  <div class="ws"><h2>Access conditions</h2><div class="fgrid"><div class="fld"><label for="wAF">At pickup</label><select id="wAF" name="accessFrom"><option>Ground floor</option><option>Elevator</option><option>Stairs: 1 flight</option><option>Stairs: 2+ flights</option><option>Long walk to truck</option></select></div><div class="fld"><label for="wAT">At delivery</label><select id="wAT" name="accessTo"><option>Ground floor</option><option>Elevator</option><option>Stairs: 1 flight</option><option>Stairs: 2+ flights</option><option>Long walk to truck</option></select></div><div class="fld full"><label for="wPark">Parking notes</label><input id="wPark" name="parking" placeholder="e.g. street parking, loading dock, permit needed"></div></div></div>
  <div class="ws"><h2>Additional services</h2><div class="fgrid">${['Furniture assembly','Junk removal','Move-out cleaning','Appliance disconnection','Packing materials delivery','Vehicle transport'].map(x=>`<label class="chk"><input type="checkbox" name="extras" value="${x}">${x}</label>`).join('')}</div></div>
  <div class="ws"><h2>Your contact details</h2><div class="fgrid"><div class="fld"><label for="wName">Full name <span class="req">*</span></label><input id="wName" name="name" autocomplete="name" required><div class="msg">Enter your full name.</div></div><div class="fld"><label for="wEmail">Email <span class="req">*</span></label><input id="wEmail" type="email" name="email" autocomplete="email" required><div class="msg">Enter a valid email address.</div></div><div class="fld"><label for="wPhone">Phone</label><input id="wPhone" type="tel" name="phone" autocomplete="tel" placeholder="Optional"></div><div class="fld"><label for="wPref">Preferred contact</label><select id="wPref" name="pref"><option>Email</option><option>Phone call</option><option>Text message</option></select></div></div></div>
  <div class="ws"><h2>Review and submit</h2><div class="review" id="wRev"></div><label class="chk"><input type="checkbox" id="wCons">I agree that MoveMatch may share these details with up to 5 matched providers to prepare quotes, and I accept the <a class="link" href="/legal/terms/">Terms</a> and <a class="link" href="/legal/privacy/">Privacy Policy</a>.</label><p id="wConsE" style="display:none;color:var(--err);font-size:14px">Please give consent to continue.</p></div>
  <div class="ws" style="text-align:center"><div class="ok-ic"><svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#15803D" stroke-width="3" stroke-linecap="round"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg></div><h2>Request saved</h2><p class="lead" style="margin:0 auto">Reference: <b id="wRef"></b></p><div class="notice info" style="text-align:left;margin-top:16px">${ic('help',20)}<div>Your request is saved in this browser. <b>It has not been sent to providers yet</b> — provider matching goes live when the MoveMatch quote service is connected. Keep your reference to look it up on <a class="link" href="/track-my-move/">Track My Move</a>.</div></div></div>
 </form>
 <div class="wnav"><button type="button" class="btn btn-o" id="wBack">← Back</button><button type="button" class="btn btn-p btn-lg" id="wNext">Continue</button></div>
 </div></div></div></section>`});

/* ============ TOOLS ============ */
const toolPage=(slug,t,lead,im,inner,extra='')=>page(`/tools/${slug}/`,{title:t,desc:lead,cr:[['Tools','/tools/moving-cost-calculator/'],[t,`/tools/${slug}/`]],body:phero([['Tools','/tools/moving-cost-calculator/'],[t]],'Moving tools',t,lead,im)+`<section><div class="wrap">${inner}</div></section>${extra}${ctaBlock()}`});
const resultBox=(h,ex)=>`<div class="res"><h3>${h}</h3><div class="rows cOut" aria-live="polite"></div>${ex?'<button class="btn btn-a" data-export style="width:100%;margin-bottom:10px">Download results</button>':''}<a class="btn btn-p" style="width:100%" href="/get-quotes/">Get real quotes ${arr}</a><p class="note">Estimates are guides only and vary by home and provider.</p></div>`;
toolPage('moving-cost-calculator','Moving Cost Calculator','See an indicative cost range for your move and how distance, size, access, services and dates affect price.','truckRoad',calcBlock,`<section class="alt"><div class="wrap split"><div class="prose rv-in"><h2>What drives moving costs</h2><ul><li><b>Distance</b> — local moves are hourly; long-distance moves are by weight or volume.</li><li><b>Volume</b> — more items means a bigger truck and crew.</li><li><b>Access</b> — stairs, long carries and elevators add time.</li><li><b>Date</b> — summer, weekends and month-end are busiest.</li><li><b>Services</b> — packing, storage and specialty items.</li></ul></div><div class="pframe rv-in">${img('unload1','',800)}</div></div></section>`);
toolPage('moving-estimate-calculator','Moving Estimate Calculator','Quick indicative estimate for your move.','semi',calcBlock);
toolPage('packing-calculator','Packing Calculator','Estimate the boxes and packing supplies you need, room by room.','packWh',`<div class="calc" data-calc="packing"><div class="card"><div class="fgrid"><div class="fld"><label for="pr">Rooms to pack (excluding kitchen)</label><input id="pr" name="rooms" type="number" min="1" max="20" value="4"></div><div class="fld"><label for="pk">Kitchens</label><input id="pk" name="kitchen" type="number" min="0" max="3" value="1"></div></div><label class="chk" style="margin-top:14px"><input type="checkbox" name="fragile">I have lots of fragile items (adds 25%)</label></div>${resultBox('Packing supplies needed',1)}</div>`);
toolPage('moving-box-calculator','Moving Box Calculator','Find out how many boxes you need by home size and household.','boxes2',`<div class="calc" data-calc="box"><div class="card"><div class="fgrid"><div class="fld"><label for="bs">Home size</label><select id="bs" name="size"><option value="0">Studio</option><option value="1" selected>1 bedroom</option><option value="2">2 bedrooms</option><option value="3">3 bedrooms</option><option value="4">4+ bedrooms</option></select></div><div class="fld"><label for="bp">People in household</label><input id="bp" name="people" type="number" min="1" max="10" value="2"></div></div></div>${resultBox('Boxes you need',1)}</div>`);
toolPage('moving-budget-planner','Moving Budget Planner','Plan every moving cost and add a contingency.','boxesTable',`<div class="calc" data-calc="budget"><div class="card"><div class="fgrid">${['Moving service','Packing','Storage','Travel','Supplies','Cleaning','Utilities set-up','Insurance / valuation'].map((c,i)=>`<div class="fld"><label for="bg${i}">${c} ($)</label><input id="bg${i}" type="number" min="0" value="${[1200,300,0,150,120,180,90,100][i]}"></div>`).join('')}</div></div>${resultBox('Your moving budget',1)}</div>`);
toolPage('moving-date-planner','Moving Date Planner','Check how busy your moving date is likely to be.','couple',`<div class="calc" data-calc="date"><div class="card"><div class="fld"><label for="md">Your planned moving date</label><input id="md" name="mdate" type="date"></div><p class="help">Tip: mid-month weekdays from October to April are usually the quietest.</p></div>${resultBox('Date assessment')}</div>`);
toolPage('volume-calculator','Volume Calculator','Estimate your move volume and the truck size you need.','yellowTruck',`<div class="calc" data-calc="volume"><div class="card"><div class="inv">${[['Sofas',1],['Beds',1],['Wardrobes / dressers',1],['Tables',1],['Chairs',2],['Appliances',1],['Boxes',20]].map(x=>`<div class="it"><span>${x[0]}</span><div class="qty"><button type="button" data-d="-1" aria-label="Fewer ${x[0]}">−</button><output>${x[1]}</output><button type="button" data-d="1" aria-label="More ${x[0]}">+</button></div></div>`).join('')}</div></div>${resultBox('Estimated volume')}</div>`);
toolPage('storage-calculator','Storage Calculator','Find the right storage unit size and a typical monthly cost.','wh3',`<div class="calc" data-calc="storage"><div class="card"><div class="fgrid"><div class="fld"><label for="sr">Rooms of furniture</label><input id="sr" name="rooms" type="number" min="1" max="5" value="2"></div><div class="fld"><label for="sm">Months</label><input id="sm" name="months" type="number" min="1" max="36" value="3"></div></div><label class="chk" style="margin-top:14px"><input type="checkbox" name="climate">Climate-controlled</label></div>${resultBox('Storage recommendation')}</div>`);
toolPage('moving-checklist','Moving Checklist Tool','Interactive moving checklist that saves your progress.','boxesRoom','<p class="lead">Your checklist lives on the <a class="link" href="/moving-checklists/">Moving Checklists</a> page.</p>');
toolPage('moving-route-planner','Moving Route Planner','Plan your route and timing between cities.','mtnTruck',`<div class="card"><p class="lead">Enter your route in a quote request and your provider will confirm drive time and delivery windows. Route estimates alone do not guarantee delivery dates.</p><a class="btn btn-p" href="/get-quotes/" style="margin-top:16px">Start a request ${arr}</a></div>`);

/* ============ INFO / PROCESS PAGES ============ */
const info=(p,cr,eye,t,lead,im,secs,aside)=>page(p,{title:t,desc:lead,cr:cr.map((c,i)=>i===cr.length-1?[c[0],p]:c),body:phero(cr.map((c,i)=>i===cr.length-1?[c[0]]:c),eye,t,lead,im)+`<section><div class="wrap cgrid"><article class="prose">${secs}</article><aside class="aside">${aside||`<div class="card"><h3>Ready to start?</h3><p class="help" style="margin:0 0 14px">Request free quotes in about 3 minutes.</p><a class="btn btn-p" style="width:100%" href="/get-quotes/">Get free quotes</a></div><div class="card"><h3>How it works</h3><a class="al" href="/how-it-works/">How MoveMatch works<span>›</span></a><a class="al" href="/compare-quotes/">Compare providers<span>›</span></a><a class="al" href="/review-estimates/">Review estimates<span>›</span></a><a class="al" href="/booking/">Book services<span>›</span></a><a class="al" href="/track-my-move/">Track your move<span>›</span></a><a class="al" href="/support/">Claims & support<span>›</span></a></div>`}</aside></div></section>${ctaBlock()}`});
const HW=[['How It Works','/how-it-works/']];
info('/how-it-works/',[['How It Works']],'The MoveMatch process','How MoveMatch Works','Four clear steps from your first question to moving day — with transparency at every stage.','couple',`<h2>1. Tell us about your move</h2><p>Enter your locations, date and property. Add an inventory and any extra services so every provider quotes on the same information.</p><div class="pframe rv-in">${img('womanBoxes','',1000)}</div><h2>2. Receive provider responses</h2><p>We match your request with providers that serve your route and offer the services you need. Providers review your details and send estimates.</p><h2>3. Compare your options</h2><p>See estimates side by side: estimate type, what's included, possible extra charges, protection options and which verification checks are complete.</p><h2>4. Book and manage your move</h2><p>Choose a provider, review the agreement, confirm your date and pay any deposit the provider requires. Then follow milestones and keep documents in one place.</p><div class="pframe rv-in">${img('unload2','',1000)}</div><h2>Our commitments</h2><ul><li>We never invent reviews, prices or availability.</li><li>Featured placements are always disclosed.</li><li>Your details go only to providers you're matched with.</li><li>Claims and disputes are reviewed by people.</li></ul>`);
page('/compare-quotes/',{title:'Compare Moving Quotes',desc:'Compare moving estimates side by side so you understand exactly what you are paying for.',cr:[...HW,['Compare Providers','/compare-quotes/']],body:phero([...HW,['Compare Providers']],'Compare','Compare Moving Quotes','Compare estimates side by side so you understand exactly what you\'re paying for.','boxesRoad')+`<section><div class="wrap"><div class="grid g4" style="margin-bottom:40px">${[['scale','Estimate type','Binding, non-binding or not-to-exceed.'],['list','Included services','Loading, transport, unloading, assembly.'],['wallet','Extra charges','Stairs, long carries, shuttles, packing.'],['shield','Verification','Which checks are complete.']].map(x=>`<div class="card hov rv-in"><div class="icb">${ic(x[0])}</div><h3 style="font-size:17px">${x[1]}</h3><p class="help">${x[2]}</p></div>`).join('')}</div><h2 class="h2" style="font-size:28px">Live comparison</h2><p class="lead" style="margin-bottom:18px">Select providers on any <a class="link" href="/movers/search/">movers page</a> to compare them here.</p>${cmpTable}</div></section>${ctaBlock()}`});
info('/review-estimates/',[...HW,['Review Estimates']],'Estimates explained','Review Moving Estimates','Understand binding, non-binding and not-to-exceed estimates before you book.','boxesTable',`<h2>Binding estimate</h2><p>The price is fixed for the items and services listed. If you add items, the estimate should be revised before moving day.</p><h2>Non-binding estimate</h2><p>An approximation. The final cost depends on the actual weight or time. Ask how the final price is calculated and any limits on increases.</p><h2>Binding not-to-exceed</h2><p>You pay the lower of the estimate or the actual cost — often the most customer-friendly option for long-distance moves.</p><h2>Red flags</h2><ul><li>A very large cash deposit up front</li><li>No written estimate or contract</li><li>No USDOT number for an interstate carrier</li><li>An estimate given without seeing or listing your items</li></ul>`);
info('/moving-inventory/',[...HW,['Prepare Inventory']],'Inventory','Prepare Your Moving Inventory','An accurate inventory means more accurate estimates — and fewer surprises on moving day.','boxesRoom',`<h2>Why inventory matters</h2><p>Providers price moves on volume, weight and handling. A room-by-room list lets everyone quote on the same information.</p><h2>What to include</h2><ul><li>Furniture by room, with quantities</li><li>Appliances and electronics</li><li>Approximate box counts</li><li>Specialty items (pianos, safes, art)</li><li>Items needing disassembly</li><li>Fragile items and notes</li></ul><p>Our quote request includes a built-in inventory builder.</p><a class="btn btn-p" href="/get-quotes/">Build my inventory ${arr}</a>`);
info('/booking/',[...HW,['Book Services']],'Booking','Book Your Move','Choose a provider, review the agreement, confirm your date and pay any deposit required.','unload1',`<h2>The booking steps</h2><ol class="tl-v">${['Select your provider','Review the estimate and contract','Choose an available date','Accept terms','Pay deposit (if the provider requires it)','Receive confirmation'].map((x,i)=>`<li><i>${i+1}</i><div><b>${x}</b></div></li>`).join('')}</ol><div class="notice info">${ic('help',20)}<div>Online booking and payments go live when providers are onboarded. A booking is only confirmed once the payment and booking systems return a successful confirmation.</div></div>`);
page('/track-my-move/',{title:'Track My Move',desc:'Follow your booking milestones from confirmation to delivery.',cr:[...HW,['Track Your Move','/track-my-move/']],body:phero([...HW,['Track Your Move']],'Tracking','Track My Move','Follow milestones from booking confirmation to delivery.','truckRoad')+`<section><div class="wrap split"><div><form class="card" id="trackForm" novalidate><h2 style="font-size:24px;margin-bottom:12px">Find your move</h2><div class="fld"><label for="tRef">Booking or request reference <span class="req">*</span></label><input id="tRef" placeholder="e.g. MM-AB12CD"><div class="msg">Enter a reference like MM-AB12CD.</div></div><button class="btn btn-p" style="margin-top:14px">Track</button><div id="tOut" hidden style="margin-top:16px"></div></form></div><div class="card"><h3 style="margin-bottom:12px">Tracking milestones</h3><ul class="status">${['Quote accepted','Booking confirmed','Crew assigned','En route to pickup','Loading','In transit','Arrived at destination','Unloading','Delivery completed'].map((s,i)=>`<li class="${i<2?'d':i===2?'c':''}"><i></i>${s}</li>`).join('')}</ul><p class="help">Example timeline. Live GPS is shown only when a provider supplies reliable tracking data.</p></div></div></section>${ctaBlock()}`});
info('/my-bookings/',[...HW,['Manage Your Booking']],'Your account','Manage Your Booking','View bookings, change dates, message your provider and manage documents.','couple',`<div class="empty"><h3>Log in to see your bookings</h3><p>Bookings, messages and documents live in your customer dashboard.</p><a class="btn btn-p" href="/login/">Log in</a> <a class="btn btn-o" href="/signup/">Create account</a></div><h2>What you can manage</h2><ul><li>Booking details and dates</li><li>Messages with your provider</li><li>Inventory changes</li><li>Documents and receipts</li><li>Cancellations under the provider's terms</li></ul>`);
info('/payments/',[...HW,['Payments']],'Payments','Payments & Receipts','Secure deposits, receipts and refunds — card details are never stored by MoveMatch.','boxesTable',`<h2>How payments work</h2><ul><li>Deposits are taken only if your provider's contract requires them.</li><li>Payments are processed by a secure payment provider.</li><li>Receipts are available in your dashboard.</li><li>Refunds follow the provider's cancellation terms.</li></ul><h2>Security</h2><p>MoveMatch never stores raw card details. Payment status is shown only after confirmation from the payment provider.</p>`);
info('/moving-documents/',[...HW,['Moving Documents']],'Documents','Moving Documents','Estimates, contracts, inventories and receipts in one place.','boxesTable',`<h2>Documents you should receive</h2><ul><li>Written estimate (with estimate type)</li><li>Order for service</li><li>Bill of lading (contract and receipt)</li><li>Inventory list</li><li>Valuation coverage details</li><li>For interstate moves: "Your Rights and Responsibilities When You Move" from the FMCSA</li></ul><p>Keep copies of everything until your move and any claims are complete.</p>`);
info('/support/',[...HW,['Claims and Support']],'Support','Claims and Support','Help with bookings, claims, complaints and provider reports — reviewed by people.','office1',`<h2>Get help</h2><div class="grid g2">${[['help','Help Center','/help-center/'],['mail','Contact support','/contact/'],['doc','File a claim','/contact/'],['flag','Report a provider','/contact/']].map(x=>`<a class="card hov" href="${x[2]}"><div class="icb">${ic(x[0])}</div><b style="color:var(--navy)">${x[1]}</b></a>`).join('')}</div><h2>Claims</h2><p>Report damage or loss as soon as possible and within your provider's claim window (for interstate moves, federal rules allow at least nine months). Include photos, your inventory and the bill of lading.</p><h2>Escalation</h2><p>Complaints, disputes and safety concerns are always escalated to a person.</p>`);

