resPage('/moving-guides/','Moving Guides','Plain-English guides for every stage of your move.','unload2',guideCards([['First-time mover\'s guide','couple','Getting started','Everything to know before your first professional move.'],['Local vs long-distance moves','semi','Planning','How pricing, timing and paperwork differ.'],['How to choose a mover','carry','Choosing','The checks that matter most before you book.'],['Moving with kids','house5','Family','Keep routines and make the move fun.'],['Moving with pets','house6','Family','Keep pets safe and calm on moving day.'],['Interstate moving rules','redTruck','Rules','USDOT numbers, estimates and your rights.']]));
resPage('/packing-guides/','Packing Guides','Pack faster, safer and smarter with room-by-room advice.','packWh',guideCards([['How to pack a kitchen','boxesTable','Room guide','Dish-packs, glasses and small appliances.'],['Packing fragile items','boxSingle','Fragile','Paper, padding and box sizes that work.'],['Packing a bedroom','boxesWindow','Room guide','Wardrobe boxes, mattresses and drawers.'],['Labelling system that works','stacked','Organising','Colour codes and room numbers.'],['Packing electronics','office3','Electronics','Cables, TVs and computers.'],['What movers won\'t move','boxesRoad','Rules','Hazardous and prohibited items.']]));
page('/moving-checklists/',{title:'Moving Checklists',desc:'Interactive 8-week moving checklist that saves your progress in your browser.',cr:[...R,['Moving Checklists','/moving-checklists/']],body:phero([...R,['Moving Checklists']],'Interactive checklist','Moving Checklists','Tick tasks off as you go — your progress is saved on this device.','boxesRoom')+`<section><div class="wrap" data-checklist="main"><div class="card" style="margin-bottom:22px"><div style="display:flex;justify-content:space-between;margin-bottom:8px"><b style="color:var(--navy)">Your progress</b><span class="ckn help" style="margin:0"></span></div><div class="prog ckp"><i></i></div></div><div class="grid g2">${[['8 weeks before',['Set a moving budget','Research moving providers','Start decluttering','Create a moving folder']],['6 weeks before',['Request and compare quotes','Order packing supplies','Measure large furniture','Plan school and work changes']],['4 weeks before',['Book your mover','Submit change of address','Notify utilities and internet','Start packing rarely-used items']],['2 weeks before',['Confirm moving date and access','Arrange elevator or parking','Arrange pet and child care','Use up frozen food']],['1 week before',['Pack remaining rooms','Pack an essentials bag','Defrost the freezer','Confirm arrival window']],['Moving day',['Walk through with the crew','Check the inventory list','Read before you sign','Final walk-through of empty home']],['After the move',['Unpack essentials first','Check for damage and report','Update your address everywhere','Leave a verified review']]].map((c,i)=>`<div class="card rv-in"><h3 style="font-size:19px;margin-bottom:10px">${c[0]}</h3>${c[1].map(x=>`<label class="chk"><input type="checkbox">${x}</label>`).join('')}</div>`).join('')}</div></div></section>${ctaBlock()}`});
