resPage('/state-guides/','State Guides','Moving to a new state? Start with the essentials for each one.','aerial',`<div class="fld" style="max-width:420px;margin-bottom:22px"><label for="stQ">Find a state</label><div class="iw">${ic('search',18)}<input id="stQ" type="search" placeholder="Type a state" oninput="var v=this.value.toLowerCase();document.querySelectorAll('.stc').forEach(function(c){c.hidden=c.textContent.toLowerCase().indexOf(v)<0})"></div></div><div class="grid g4">${STATES.map(s=>`<a class="card hov stc" href="/get-quotes/" data-seed='{"to":"${s}"}' style="padding:18px;display:flex;justify-content:space-between;align-items:center"><b style="color:var(--navy)">${s}</b>${ic('arrow',16)}</a>`).join('')}</div>`);
resPage('/moving-cost-guides/','Moving Cost Guides','How moving prices are calculated — and how to save.','truckRoad',`<div class="grid g3">${[['Local moves','Hourly rate × crew size × hours, plus travel time and materials.','road'],['Long-distance moves','Weight or volume × distance, plus accessorial charges.','map'],['Extra charges','Stairs, long carries, shuttle trucks, packing and storage.','list']].map(x=>`<div class="card hov"><div class="icb">${ic(x[2])}</div><h3>${x[0]}</h3><p class="help">${x[1]}</p></div>`).join('')}</div><div class="prose" style="margin-top:40px"><h2>Ways to save</h2><ul><li>Move midweek and mid-month</li><li>Declutter before quotes</li><li>Pack yourself</li><li>Compare several estimates</li><li>Choose flexible dates</li></ul><a class="btn btn-p" href="/tools/moving-cost-calculator/">Try the cost calculator ${arr}</a></div>`);
