page('/faqs/',{title:'Frequently Asked Questions',desc:'Answers about quotes, verification, estimates, payments, tracking and claims.',cr:[...R,['FAQs','/faqs/']],body:phero([...R,['FAQs']],'FAQs','Frequently Asked Questions','Answers about quotes, verification, estimates, payments, tracking and claims.','desk')+`<section><div class="wrap faqw">${faqBlock(FAQS.concat([['Can I cancel a booking?','Yes. Cancellation terms are set by your provider and shown before you book.'],['Is my data shared?','Your details are shared only with providers matched to your request and never sold.'],['Do you cover international moves?','We list international movers; customs and shipping are handled by the provider.']]),true)}</div></section>${ctaBlock()}`,schema:{"@context":"https://schema.org","@type":"FAQPage","mainEntity":FAQS.map(f=>({"@type":"Question","name":f[0],"acceptedAnswer":{"@type":"Answer","text":f[1]}}))}});
