page('/contact/',{title:'Contact Support',desc:'Contact MoveMatch support for help with quotes, bookings, claims or complaints.',cr:[...R,['Contact Support','/contact/']],body:phero([...R,['Contact Support']],'Support','Contact Support','Questions, claims, complaints or provider reports — a person reviews every claim and complaint.','office2')+`<section><div class="wrap split" style="align-items:start"><div class="card"><form data-form="contact" novalidate class="fgrid"><div class="fld full"><label for="ct">Topic</label><select id="ct" name="topic"><option>General question</option><option>Booking support</option><option>Claim</option><option>Complaint</option><option>Report a provider</option><option>Security issue</option></select></div><div class="fld"><label for="cn">Name <span class="req">*</span></label><input id="cn" name="name" required autocomplete="name"><div class="msg">Enter your name.</div></div><div class="fld"><label for="ce">Email <span class="req">*</span></label><input id="ce" type="email" name="email" required autocomplete="email"><div class="msg">Enter a valid email.</div></div><div class="fld full"><label for="cr">Booking reference</label><input id="cr" name="ref" placeholder="Optional"></div><div class="fld full"><label for="cm">Message <span class="req">*</span></label><textarea id="cm" name="msg" rows="5" required></textarea><div class="msg">Enter a message.</div></div><button class="btn btn-p full" type="submit">Send message</button></form><div class="fdone" hidden tabindex="-1" style="text-align:center"><div class="ok-ic"><svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#15803D" stroke-width="3"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg></div><h3>Message saved</h3><p class="help">Your message is saved on this device. The support inbox connects when the MoveMatch backend goes live.</p></div></div><div><div class="pframe">${img('office2','',800)}</div><ul class="ulist"><li><span class="tk">${tick}</span><div><b>Claims & complaints</b><br>Reviewed by a person, never only automated.</div></li><li><span class="tk">${tick}</span><div><b>Provider reports</b><br>Flag safety or conduct concerns.</div></li></ul></div></div></section>`});

