const B=[['For Businesses','/for-movers/']];
const appForm=`<div class="card"><form data-form="partner" novalidate class="fgrid">${[['Legal business name','text',1],['Trading name','text',0],['Contact person','text',1],['Email','email',1],['Phone','tel',1],['Website','url',0],['Business address','text',1],['Service areas (cities/states)','text',1]].map((f,i)=>`<div class="fld${i>5?' full':''}"><label for="pa${i}">${f[0]}${f[2]?' <span class="req">*</span>':''}</label><input id="pa${i}" type="${f[1]}" ${f[2]?'required':''}><div class="msg">This field is required.</div></div>`).join('')}<div class="fld"><label for="paT">Provider type</label><select id="paT"><option>Carrier</option><option>Broker</option><option>Local mover</option><option>Storage provider</option><option>Service partner</option></select></div><div class="fld"><label for="paD">USDOT / MC number</label><input id="paD" placeholder="Required for interstate carriers"></div><div class="fld full"><span class="flab">Service categories</span><div class="fgrid">${['Local','Long-distance','Commercial','Packing','Storage','Specialty'].map(x=>`<label class="chk"><input type="checkbox">${x}</label>`).join('')}</div></div><label class="chk full"><input type="checkbox" required>I consent to MoveMatch verifying my business, licence and insurance details.</label><button class="btn btn-p btn-lg full" type="submit">Submit application</button></form><div class="fdone" hidden tabindex="-1" style="text-align:center"><div class="ok-ic"><svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#15803D" stroke-width="3"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg></div><h3>Application saved</h3><p class="help">Saved on this device. Applications are reviewed once the partner onboarding service is connected. Profiles are never published before review.</p></div></div>`;
page('/for-movers/',{title:'Join as a Mover',desc:'Grow your moving business with qualified requests, itemised quotes, bookings and payments in one dashboard.',cr:[...B],body:phero([['For Businesses']],'For moving companies','Grow your moving business with MoveMatch','Qualified requests, itemised quotes, booking management and payments — in one dashboard.','wh1',`<div class="ctas st st3"><a href="/for-movers/register/" class="btn btn-p btn-lg">Apply as a Mover ${arr}</a><a href="/for-movers/verification/" class="btn btn-w btn-lg">Verification process</a></div>`)+`<section><div class="wrap"><div class="grid g3">${[['users','Qualified leads','Requests matched to your area and services.'],['doc','Itemised quotes','Send estimates with full revision history.'],['cal','Bookings & crews','Schedule jobs and message customers.'],['wallet','Payments','Deposits, receipts and refunds.'],['chart','Analytics','Response rate and conversion insight.'],['shield','Transparent profile','Each verification check shown clearly.']].map(b=>`<div class="card hov rv-in"><div class="icb">${ic(b[0])}</div><h3>${b[1]}</h3><p class="help">${b[2]}</p></div>`).join('')}</div></div></section><section class="alt"><div class="wrap split"><div class="rv-in"><p class="eyebrow">How it works for providers</p><h2 class="h2">From application to first booking</h2><ol class="tl-v">${['Apply with your business details','Complete verification checks','Set service areas and capacity','Receive matched requests','Send quotes and win bookings'].map((x,i)=>`<li><i>${i+1}</i><div><b>${x}</b></div></li>`).join('')}</ol><a class="btn btn-s" href="/for-movers/register/">Start application ${arr}</a></div><div class="pframe rv-in">${img('unload1','',800)}</div></div></section>${ctaBlock('Ready to grow?','Apply in minutes. Profiles go live after review.')}`});
info('/for-movers/benefits/',[...B,['Moving Company Benefits']],'Benefits','Moving Company Benefits','Why moving companies choose MoveMatch.','forklift',`<h2>More of the right customers</h2><p>Requests are matched to your service areas, categories and capacity — no paying for leads you can't serve.</p><h2>Run your business in one place</h2><ul><li>Lead inbox and quote builder</li><li>Booking calendar and crew assignment</li><li>Customer messaging</li><li>Payments and receipts</li><li>Performance analytics</li></ul><h2>Fair and transparent</h2><p>Paid placement is always disclosed and never changes reviews or verification.</p>`,`<div class="card"><h3>Apply today</h3><a class="btn btn-p" style="width:100%" href="/for-movers/register/">Partner registration</a></div>`);
