simple('/box-labels/',[['Resources','/moving-guides/'],['Box Labels']],'Packing tools','Printable Box Labels','Create numbered box labels by room, with fragile and open-first flags. Print and stick.','boxes2',
`<div class="card no-print" style="margin-bottom:22px"><form id="blF" class="fgrid" novalidate style="grid-template-columns:repeat(auto-fit,minmax(180px,1fr))"><div class="fld"><label for="blR">Room</label><select id="blR">${['Living room','Bedroom','Kitchen','Bathroom','Dining room','Garage','Office','Kids room'].map(r=>`<option>${r}</option>`).join('')}</select></div><div class="fld"><label for="blN">Number of boxes</label><input id="blN" type="number" min="1" max="60" value="6"></div><div class="fld"><label for="blC">Contents (optional)</label><input id="blC"></div><label class="chk"><input type="checkbox" id="blFr">Fragile</label><label class="chk"><input type="checkbox" id="blOF">Open first</label><button class="btn btn-s">Add labels</button><button class="btn btn-o" type="button" onclick="window.print()">Print</button></form></div><div id="blOut" class="grid g3"></div><style>@media print{header,.ann,footer,.phero,.no-print,.fcta,.mbar,.toast,#ckBanner{display:none!important}.lbl-card{break-inside:avoid}}</style>`);

/* Loyalty (78) */
simple('/rewards/',[['Resources','/moving-guides/'],['Rewards']],'Loyalty','MoveMatch Rewards','Earn points on bookings and referrals. Your inventory and preferences carry over to your next move.','couple',
`<div class="grid g3" style="margin-bottom:30px">${[['Member','0+ points','Saved inventory & preferences'],['Silver','1,000+ points','Priority support'],['Gold','3,000+ points','Dedicated concierge on eligible moves']].map((t,i)=>`<div class="card hov rv-in" style="${i===2?'border:2px solid var(--amber)':''}"><h3>${t[0]}</h3><p style="font:800 20px var(--fh);color:var(--tealD)">${t[1]}</p><p class="help">${t[2]}</p></div>`).join('')}</div><div class="card" style="max-width:560px"><h3 style="margin-bottom:10px">Your referral link</h3><div style="display:flex;gap:8px"><input class="fld" id="refL" readonly style="flex:1;min-width:0;min-height:48px;border:1.5px solid var(--n3);border-radius:10px;padding:0 12px" value=""><button class="btn btn-p" id="refC" type="button">Copy</button></div><p class="help">Rewards launch with live bookings. Terms will be published before launch.</p></div>`);

/* Our promises (36) */
simple('/our-promises/',[['How It Works','/how-it-works/'],['Our Promises']],'Non-negotiable rules','Our 15 Promises','The rules every part of MoveMatch is built on.','house2',
`<div class="grid g3">${['No hidden charges','No fake reviews','No misleading provider identity','No false tracking claims','No unverified insurance claims','No silent quote changes','No provider swaps without your approval','No payment manipulation','No deletion of financial audit history','No AI actions beyond permissions','No cross-account data exposure','No fake availability','No fabricated ratings','No unverified compliance badges','No data use beyond what you agreed'].map((p,i)=>`<div class="card hov rv-in" style="display:flex;gap:14px;align-items:center;padding:20px"><span style="font:800 22px var(--fh);color:var(--teal);min-width:32px">${String(i+1).padStart(2,'0')}</span><b style="color:var(--navy)">${p}</b></div>`).join('')}</div>`);

/* Platform overview (4, 62, 35) */
simple('/platform/',[['For Businesses','/for-movers/'],['The MoveMatch Platform']],'One connected ecosystem','The MoveMatch Platform','One Marketplace + One Moving Project + One Company OS + One Partner Network + One Intelligence Layer.','office4',
`<div class="grid g4" style="margin-bottom:56px">${[['Customer Marketplace','search','/moving-methods/'],['Customer Moving OS','home','/dashboard/'],['Moving Company OS','truck','/company-os/'],['Provider & Partner OS','users','/for-movers/'],['Crew, Fleet & Warehouse','warehouse','/company-os/'],['Storage, Packing & Rental','storage','/package-builder/'],['Enterprise Relocation','building','/enterprise/portal/'],['Payments & Claims','wallet','/claims/'],['AI & Automation','spark','/platform/#ai'],['Founder Admin OS','chart','/admin/'],['Developer Platform','code','/developer/docs/'],['Future Technology Layer','globe','/platform/#roadmap']].map((p,i)=>`<a class="card hov rv-in" href="${p[2]}" style="transition-delay:${(i%4)*50}ms"><div class="icb">${ic(p[1])}</div><h3 style="font-size:17px">${p[0]}</h3><span class="link">Open ${arr}</span></a>`).join('')}</div>
<div id="ai" class="split" style="margin-bottom:56px"><div><p class="eyebrow">Intelligence layer</p><h2 class="h2">AI with guardrails</h2><ul class="ulist">${['Inventory suggestions you confirm before pricing','Quote completeness and price-anomaly checks','Dispatch conflict detection','Delay prediction and alternatives','Human approval for every consequential action','Every AI action logged and permission-scoped'].map(x=>`<li><span class="tk">${tick}</span>${x}</li>`).join('')}</ul></div><div class="pframe">${img('desk','',800)}</div></div>
<div id="roadmap"><p class="eyebrow">Roadmap</p><h2 class="h2">Built in stages</h2><ol class="tl-v">${[['Phase 0','Business & legal foundation'],['Phase 1','Core marketplace'],['Phase 2','Moving Company OS'],['Phase 3','Complete Moving Project'],['Phase 4','Expanded marketplace'],['Phase 5','Enterprise & international'],['Phase 6','AI intelligence'],['Phase 7','Digital twins, AR, IoT & robotics integrations']].map((r,i)=>`<li><i>${i}</i><div><b>${r[0]}</b><span>${r[1]}</span></div></li>`).join('')}</ol><p class="help">The front-end previews on this site cover discovery, quoting and demo dashboards. Backend services are built phase by phase.</p></div>`);


