/* ============ V7: 150-feature frontend spec (consolidated) ============ */
const LRN=[['Learn','/learn/']];

/* --- My Moving Space (F1-15, 42, 89, 97, 68, 69, 128-130, 136, 140, 148) --- */
const CK=(id,title,items)=>`<div class="card" data-mmlist="${id}"><div style="display:flex;justify-content:space-between;align-items:center;gap:10px"><h3 style="font-size:18px">${title}</h3><span class="bdg mm-cnt">0/${items.length}</span></div><div class="prog" style="margin:10px 0 12px"><i></i></div>${items.map(i=>`<label class="chk"><input type="checkbox">${i}</label>`).join('')}</div>`;
page('/my-move/',{title:'My Moving Space',desc:'Your personal moving workspace: readiness score, timeline, checklists, packing tracker, expenses, documents, emergency info and printable moving-day schedule.',cr:[['My Moving Space','/my-move/']],
body:`<section class="phero" style="padding:56px 0 64px">${img('couple','',1600,true).replace('<img','<img class="bg"')}<div class="wrap">${crumbs([['My Moving Space']])}<div style="display:grid;grid-template-columns:1fr auto;gap:24px;align-items:center" class="mm-hero"><div><p class="eyebrow" style="color:var(--teal)">Your personal workspace</p><h1 class="st st1" style="margin-bottom:10px">My Moving Space</h1><p class="lead st st2">Everything for your move in one place — saved privately on this device.</p>
<div class="fgrid st st3" style="max-width:520px;margin-top:18px"><div class="fld"><label for="mmDate" style="color:#fff">Moving date</label><input type="date" id="mmDate"></div><div class="fld"><label for="mmName" style="color:#fff">Plan name</label><input id="mmName" placeholder="e.g. Austin → Denver"></div></div></div>
<div class="mm-ring st st4" aria-live="polite"><svg viewBox="0 0 120 120" width="170" height="170" role="img" aria-label="Readiness score"><circle cx="60" cy="60" r="50" fill="none" stroke="rgba(255,255,255,.15)" stroke-width="12"/><circle id="mmArc" cx="60" cy="60" r="50" fill="none" stroke="#14B8A6" stroke-width="12" stroke-linecap="round" stroke-dasharray="314" stroke-dashoffset="314" transform="rotate(-90 60 60)" style="transition:stroke-dashoffset .8s"/><text id="mmPct" x="60" y="62" text-anchor="middle" font-size="26" font-weight="800" fill="#fff" font-family="Manrope,Arial">0%</text><text x="60" y="82" text-anchor="middle" font-size="10" fill="#D9E2EC">ready</text></svg><p id="mmDays" style="text-align:center;color:#fff;font-weight:600;margin:4px 0 0"></p></div></div></div></section>
<section style="padding-top:40px"><div class="wrap">
<div class="mm-actions no-print" style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:22px"><button class="btn btn-s" id="mmShare" type="button">${ic('arrow',16)} Share plan</button><button class="btn btn-o" id="mmExport" type="button">${ic('doc',16)} Download report</button><button class="btn btn-o" type="button" onclick="window.print()">Print</button><button class="btn btn-g" id="mmReset" type="button">Reset</button><span class="help" style="margin:auto 0 auto auto">${ic('lock',14)} Stored only in this browser · works offline</span></div>
<div class="tabs" role="tablist" aria-label="My Moving Space">${['Next steps','Timeline','Checklists','Packing tracker','Expenses','Documents','Moving day'].map((t,i)=>`<button class="tab" role="tab" id="mt${i}" aria-selected="${!i}" aria-controls="mp${i}" tabindex="${i?-1:0}">${t}</button>`).join('')}</div>
<div role="tabpanel" id="mp0" aria-labelledby="mt0"><div class="grid g3" id="mmNext"></div><h3 class="sa-h" style="margin-top:28px">Recommended for you</h3><div class="grid g4" id="mmRec"></div></div>
<div role="tabpanel" id="mp1" aria-labelledby="mt1" hidden><div class="card"><ol class="tl-v" id="mmTL"></ol></div></div>
<div role="tabpanel" id="mp2" aria-labelledby="mt2" hidden><div class="grid g2">
${CK('addr','Address change',['USPS change of address','Bank & credit cards','Employer / payroll','Driver\'s license & vehicle registration','Voter registration','Insurance (home, auto, health)','Subscriptions & deliveries','Doctors, dentist & pharmacy'])}
${CK('util','Utilities',['Electricity — stop & start','Gas — stop & start','Water & sewer','Trash & recycling','Internet installation booked','Return old router / cable box'])}
${CK('family','School & family',['Request school records','Register at new school','Transfer medical records','Find new pediatrician','Arrange childcare on moving day','Plan a first-night box for each child'])}
${CK('pets','Pets',['Vet records & prescriptions','Update microchip address','Pet carrier & travel supplies','Plan quiet room on moving day','Check pet rules at new home'])}
</div></div>
<div role="tabpanel" id="mp3" aria-labelledby="mt3" hidden><div class="grid g3" id="mmRooms"></div><form id="mmRoomAdd" class="card no-print" style="display:flex;gap:8px;margin-top:16px;flex-wrap:wrap" novalidate><label for="mmRoomN" class="sr">Room name</label><input id="mmRoomN" class="fld" placeholder="Add a room (e.g. Attic)" style="flex:1;min-width:0;min-height:46px;border:1.5px solid var(--n3);border-radius:10px;padding:0 12px"><button class="btn btn-s">Add room</button></form></div>
<div role="tabpanel" id="mp4" aria-labelledby="mt4" hidden><div class="calc" style="align-items:start"><div class="card"><form id="mmExpF" class="fgrid" novalidate><div class="fld"><label for="exD">Item</label><input id="exD" placeholder="e.g. Packing boxes" required><div class="msg">Describe the expense.</div></div><div class="fld"><label for="exA">Amount ($)</label><input id="exA" type="number" min="0" step="0.01" required><div class="msg">Enter an amount.</div></div><div class="fld"><label for="exC">Category</label><select id="exC">${['Moving service','Packing','Storage','Travel','Supplies','Cleaning','Utilities','Other'].map(c=>`<option>${c}</option>`).join('')}</select></div><div class="fld"><label for="exB">Total budget ($)</label><input id="exB" type="number" min="0" value="3000"></div><button class="btn btn-s full">Add expense</button></form><div class="tbl" style="margin-top:14px"><table><thead><tr><th>Item</th><th>Category</th><th>Amount</th><th></th></tr></thead><tbody id="exT"></tbody></table></div></div><div class="res"><h3>Budget</h3><div class="big" id="exTot">$0</div><div class="meter"><i id="exBar"></i></div><div class="rows" id="exCats"></div></div></div></div>
<div role="tabpanel" id="mp5" aria-labelledby="mt5" hidden>${CK('docs','Important documents',['Moving estimate (with estimate type)','Order for service','Bill of lading','Inventory list','Valuation / protection details','Lease or closing documents','IDs & passports (carry with you)','Medical & school records','Vehicle titles & registration','Pet records'])}<p class="help">Tip: keep originals with you on moving day — never pack them in the truck.</p></div>
<div role="tabpanel" id="mp6" aria-labelledby="mt6" hidden><div class="split" style="align-items:start"><div class="card"><h3 style="margin-bottom:12px">Moving-day schedule</h3><div id="mmSched"></div><button class="btn btn-o no-print" id="mmSchedAdd" type="button" style="margin-top:10px">Add time slot</button></div><div class="card"><h3 style="margin-bottom:12px">Emergency information</h3><form id="mmEm" class="fgrid" novalidate>${[['Mover dispatch phone','tel'],['Crew lead name','text'],['Building manager','text'],['Emergency contact','tel'],['Pickup access notes','text'],['Delivery access notes','text']].map((f,i)=>`<div class="fld${i>3?' full':''}"><label for="em${i}">${f[0]}</label><input id="em${i}" type="${f[1]}" data-em="${i}"></div>`).join('')}</form><p class="help">In an emergency call 911. Saved on this device only.</p></div></div></div>
</div></section>`});

/* --- Learning Center (F46-60, 9, 10, 44, 100, 104-108, 111-115, 119-120) --- */
const learn=(slug,t,lead,im,body)=>page(`/learn/${slug}/`,{title:t,desc:lead,cr:[...LRN,[t,`/learn/${slug}/`]],body:phero([...LRN,[t]],'Learning center',t,lead,im)+`<section><div class="wrap cgrid"><article class="prose">${body}</article><aside class="aside"><div class="card"><h3>More in Learn</h3>${LEARN.filter(l=>l[0]!==slug).slice(0,7).map(l=>`<a class="al" href="/learn/${l[0]}/">${l[1]}<span>›</span></a>`).join('')}</div><div class="card"><h3>Ready to compare?</h3><a class="btn btn-p" style="width:100%" href="/get-quotes/">Get free quotes</a></div></aside></div></section>${ctaBlock()}`});
const LEARN=[['estimates','Understanding Moving Estimates','scale','boxesTable','Binding, non-binding and not-to-exceed — with an interactive example.'],['protection','Moving Protection & Valuation','shield','boxSingle','Released value vs full value protection vs insurance.'],['scams','Moving Fraud Awareness','flag','semi','Red flags and a quick self-check.'],['credentials','Mover Credentials Explained','doc','office3','USDOT, MC numbers, licences and insurance.'],['interstate-rules','Interstate Moving Rules','map','redTruck','Your rights and the documents you should receive.'],['claims-prep','Preparing a Moving Claim','list','boxesTable','Evidence, deadlines and what to expect.'],['how-we-compare','How MoveMatch Compares','search','boxesRoad','Ranking factors, sponsored labels and reviews.'],['pets','Moving With Pets','heart','house5','A calm plan for dogs, cats and more.'],['vehicles','Shipping a Vehicle','car','carCarrier','Open vs enclosed transport and how to prepare.'],['seasons','Seasonal Moving Guide','cal','house3','How each season affects price and planning.'],['glossary','Moving Glossary','list','boxesWindow','Searchable dictionary of moving terms.']];
page('/learn/',{title:'Moving Learning Center',desc:'Plain-English guides to estimates, protection, scams, credentials, interstate rules, claims, pets, vehicles and moving terms.',cr:[...LRN],body:phero([['Learn']],'Learning center','Learn before you move','Clear, honest explanations — so you can compare movers with confidence.','boxesRoom')+`<section><div class="wrap"><div class="grid g3">${LEARN.map((l,i)=>`<a href="/learn/${l[0]}/" class="card rcard rv-in" style="transition-delay:${(i%3)*60}ms"><div class="ph">${img(l[3],'',600)}</div><div class="rb"><small>${ic(l[2],14)} Guide</small><h3>${l[1]}</h3><p>${l[4]}</p><span class="link">Read ${arr}</span></div></a>`).join('')}</div></div></section>${ctaBlock()}`});
learn('estimates','Understanding Moving Estimates','How estimate types work — and what happens when your shipment weighs more than expected.','boxesTable',`<h2>Three estimate types</h2><div class="grid g3" style="margin-bottom:20px">${[['Non-binding','The final price depends on the actual weight or time. It can go up.'],['Binding','A fixed price for the listed items and services.'],['Binding not-to-exceed','You pay the lower of the estimate or the actual cost.']].map(x=>`<div class="card"><b style="color:var(--navy)">${x[0]}</b><p class="help">${x[1]}</p></div>`).join('')}</div>
<h2>Try it</h2><div class="card" id="estX"><div class="fgrid"><div class="fld"><label for="eqE">Estimate amount ($)</label><input id="eqE" type="number" value="3000"></div><div class="fld"><label for="eqA">Actual cost after weighing ($)</label><input id="eqA" type="number" value="3600"></div></div><div class="tbl" style="margin-top:14px"><table><thead><tr><th>Estimate type</th><th>You pay (illustration)</th></tr></thead><tbody id="eqOut"></tbody></table></div><p class="help">Simplified illustration. For interstate moves, federal rules limit how much more you can be asked to pay at delivery on a non-binding estimate — ask your mover and read your documents.</p></div>
<h2>What every estimate should show</h2><ul><li>The estimate type, in writing</li><li>Your inventory or the survey it is based on</li><li>Included services and exclusions</li><li>Possible extra charges (stairs, long carry, shuttle)</li><li>Valuation / protection option</li><li>How long the price is valid</li></ul>`);
learn('protection','Moving Protection & Valuation','Carrier liability is not the same as insurance. Here is how the options differ.','boxSingle',`<h2>Compare the options</h2><div class="tbl"><table><thead><tr><th></th><th>Released value</th><th>Full value protection</th><th>Third-party insurance</th></tr></thead><tbody><tr><th scope="row">What it is</th><td>Basic carrier liability</td><td>Carrier repairs, replaces or pays current value</td><td>Separate insurance policy</td></tr><tr><th scope="row">Typical cost</th><td>Usually no extra charge</td><td>Extra charge</td><td>Policy premium</td></tr><tr><th scope="row">Payout basis</th><td>By weight (interstate: $0.60/lb per item)</td><td>Repair, replace or value, subject to terms</td><td>Per policy terms</td></tr></tbody></table></div>
<h2>See the difference</h2><div class="card" id="valX"><div class="fgrid"><div class="fld"><label for="vlW">Item weight (lb)</label><input id="vlW" type="number" value="10"></div><div class="fld"><label for="vlV">Item value ($)</label><input id="vlV" type="number" value="1200"></div></div><div class="rows light" id="vlOut" style="margin-top:12px"></div><p class="help">Illustration only. Deductibles, limits and exclusions apply — read your mover's terms.</p></div>`);
learn('scams','Moving Fraud Awareness','Most movers are honest. These warning signs help you spot the ones that are not.','semi',`<h2>Red-flag self-check</h2><div class="card" id="scamX">${['Asked for a large cash deposit','No written estimate','Estimate given without seeing or listing items','No USDOT number for an interstate move','Company name changes or no local address','Pressured to sign blank or incomplete documents','Price far below every other quote','Truck arrives unmarked'].map(x=>`<label class="chk"><input type="checkbox">${x}</label>`).join('')}<p id="scamOut" style="font-weight:700;margin-top:12px"></p></div><h2>Protect yourself</h2><ul><li>Get several written estimates</li><li>Check the company's USDOT number on the FMCSA website</li><li>Pay deposits by card, not cash</li><li>Read every document before signing</li><li>Keep copies of everything</li></ul><p><a class="link" href="https://www.fmcsa.dot.gov/protect-your-move" target="_blank" rel="noopener">FMCSA: Protect Your Move ↗</a></p>`);
learn('credentials','Mover Credentials Explained','What USDOT and MC numbers mean, and how MoveMatch shows each verification check.','office3',`<h2>Common credentials</h2><ul><li><b>USDOT number</b> — required for interstate household-goods carriers.</li><li><b>MC number</b> — operating authority for many interstate movers and brokers.</li><li><b>State licence</b> — some states license intrastate movers.</li><li><b>Insurance certificate</b> — proof of liability and cargo coverage.</li></ul><h2>Look up a company</h2><p>You can check a carrier on the FMCSA SAFER system.</p><p><a class="btn btn-o" href="https://safer.fmcsa.dot.gov/CompanySnapshot.aspx" target="_blank" rel="noopener">Open FMCSA SAFER ↗</a></p><h2>How MoveMatch verifies</h2><ol class="tl-v">${['Application submitted','Identity check','Business registration check','Licence / USDOT check (where required)','Insurance check','Profile published with each check shown','Periodic re-verification'].map((s,i)=>`<li><i>${i+1}</i><div><b>${s}</b></div></li>`).join('')}</ol>`);
learn('interstate-rules','Interstate Moving Rules','Federal rules protect you when moving across state lines.','redTruck',`<h2>Documents you should receive</h2><ul><li>Written estimate</li><li>Order for service</li><li>Bill of lading</li><li>Inventory</li><li>"Your Rights and Responsibilities When You Move"</li><li>Information about dispute settlement</li></ul><h2>Key points</h2><ul><li>Interstate carriers must be registered with the FMCSA.</li><li>You can choose released value or full value protection.</li><li>Claims for loss or damage generally may be filed within nine months of delivery.</li></ul><p class="help">General information, not legal advice. Check the FMCSA website for current rules.</p><p><a class="link" href="https://www.fmcsa.dot.gov/protect-your-move" target="_blank" rel="noopener">FMCSA Protect Your Move ↗</a></p>`);
learn('claims-prep','Preparing a Moving Claim','Good evidence makes claims faster and fairer.','boxesTable',`<h2>Before the move</h2><ul><li>Photograph valuable items and existing damage</li><li>Keep receipts and appraisals</li><li>Make sure the inventory is accurate</li></ul><h2>At delivery</h2><ul><li>Inspect items before the crew leaves</li><li>Note visible damage on the delivery paperwork</li><li>Do not sign "received in good condition" if it is not</li></ul><h2>Filing</h2><ul><li>Report as soon as possible</li><li>Include photos, inventory numbers and the bill of lading</li><li>Keep all communication in writing</li></ul><p><a class="btn btn-p" href="/claims/">Go to the Claims Center</a></p>`);
learn('how-we-compare','How MoveMatch Compares Movers','Our comparison rules, sponsored labels and review policy.','boxesRoad',`<h2>Ranking factors</h2><ul><li>Match to your service, route and date</li><li>Completed verification checks</li><li>Verified reviews from completed bookings</li><li>Completion and response reliability</li><li>Price — when estimates are comparable</li></ul><h2>Sponsored placements</h2><p>Sponsored providers are always labelled <span class="sample">Sponsored</span>. Payment never changes verification, ratings or eligibility.</p><h2>Reviews</h2><p>Only customers with a completed booking can leave a verified review. Reviews are moderated under a published policy and are never removed to improve rankings.</p><div class="notice">${ic('help',20)}<div>Provider profiles on this site are currently samples — no ratings are shown until real verified reviews exist.</div></div>`);
learn('pets','Moving With Pets','A calm, safe plan for moving day.','house5',`<h2>Two weeks before</h2><ul><li>Visit the vet; get records and refills</li><li>Update microchip and ID tags</li><li>Get your pet used to its carrier</li></ul><h2>Moving day</h2><ul><li>Keep pets in a quiet, closed room or with a sitter</li><li>Pack a pet kit: food, water, bowls, leash, litter, medicine</li><li>Never transport pets in the moving truck</li></ul><h2>After arrival</h2><ul><li>Pet-proof the new home</li><li>Keep routines consistent</li><li>Register with a local vet</li></ul><p><a class="link" href="/my-move/">Track pet tasks in My Moving Space ${arr}</a></p>`);
learn('vehicles','Shipping a Vehicle','Open or enclosed transport, and how to prepare your car.','carCarrier',`<h2>Open vs enclosed</h2><div class="tbl"><table><thead><tr><th></th><th>Open carrier</th><th>Enclosed carrier</th></tr></thead><tbody><tr><th scope="row">Cost</th><td>Lower</td><td>Higher</td></tr><tr><th scope="row">Protection</td><td>Exposed to weather</td><td>Fully covered</td></tr><tr><th scope="row">Best for</th><td>Everyday cars</td><td>Classic, luxury or low-clearance cars</td></tr></tbody></table></div><h2>Preparation</h2><ul><li>Wash and photograph the car from all sides</li><li>Remove personal items and toll tags</li><li>Leave about a quarter tank of fuel</li><li>Note existing damage on the inspection report</li></ul><p><a class="btn btn-p" href="/services/vehicle-transport/">Vehicle transport quotes</a></p>`);
learn('seasons','Seasonal Moving Guide','How the time of year affects price, availability and planning.','house3',`<div class="tabs" role="tablist" aria-label="Seasons">${['Spring','Summer','Fall','Winter'].map((s,i)=>`<button class="tab" role="tab" id="se${i}" aria-selected="${!i}" aria-controls="sp${i}" tabindex="${i?-1:0}">${s}</button>`).join('')}</div>${[['Moderate demand','Rising prices from May','Book 4–6 weeks ahead','Spring rain — protect floors'],['Peak season','Highest prices','Book 6–8 weeks ahead','Heat — move early in the day, hydrate'],['Demand drops after Labor Day','Better rates','2–4 weeks is often enough','Ideal weather in much of the US'],['Lowest demand','Best prices & availability','Flexible dates easy','Snow & ice — plan routes and salt paths']].map((s,i)=>`<div role="tabpanel" id="sp${i}" aria-labelledby="se${i}" ${i?'hidden':''}><ul><li><b>Demand:</b> ${s[0]}</li><li><b>Price:</b> ${s[1]}</li><li><b>Booking:</b> ${s[2]}</li><li><b>Weather:</b> ${s[3]}</li></ul></div>`).join('')}<p><a class="link" href="/tools/moving-date-planner/">Check your date in the Date Planner ${arr}</a></p>`);
const GLOSS=[['Accessorial charges','Fees for extra services beyond transport, such as stairs, long carry or packing.'],['Bill of lading','The contract and receipt for your shipment.'],['Binding estimate','A fixed price for the listed items and services.'],['Binding not-to-exceed','You pay the lower of the estimate or actual cost.'],['Broker','A company that arranges a move with a carrier but does not move goods itself.'],['Carrier','The company that physically transports your belongings.'],['COI','Certificate of insurance, often required by buildings.'],['Crating','Building a custom wooden crate to protect fragile items.'],['Cubic feet','A volume measure used to size moves and trucks.'],['Delivery spread','The window of days in which delivery may occur.'],['Dish-pack','A heavy-duty box for dishes and glassware.'],['Elevator fee','Charge for using elevators at pickup or delivery.'],['Estimate','A mover\'s price for your move based on an inventory or survey.'],['Flight charge','Fee per flight of stairs.'],['FMCSA','Federal Motor Carrier Safety Administration, which regulates interstate movers.'],['Full value protection','The carrier repairs, replaces or pays current value of lost or damaged items, subject to terms.'],['Inventory','A detailed list of items being moved.'],['Long carry','Extra charge when the truck can\'t park near the door.'],['MC number','Operating authority number for many interstate carriers and brokers.'],['Non-binding estimate','An approximate price that may change with actual weight or time.'],['Order for service','Document authorising the mover to perform the move.'],['Released value','Basic carrier liability, paid by weight.'],['Shuttle service','A smaller truck used when a large truck can\'t reach the home.'],['Storage-in-transit','Temporary storage during an interstate move.'],['Survey','An in-home or video walkthrough to estimate a move.'],['Tariff','A carrier\'s published list of rates and rules.'],['USDOT number','Federal registration number for commercial carriers.'],['Valuation','The level of carrier liability for your goods.'],['Weight ticket','A certified scale record of a truck\'s weight.']];
learn('glossary','Moving Glossary','Searchable dictionary of moving terms.','boxesWindow',`<div class="fld" style="margin-bottom:18px"><label for="glQ">Search terms</label><div class="iw">${ic('search',18)}<input id="glQ" type="search" placeholder="e.g. bill of lading"></div></div><div id="glL">${GLOSS.map(g=>`<div class="card gl" style="margin-bottom:10px;padding:18px"><b style="color:var(--navy)">${g[0]}</b><p class="help" style="margin:4px 0 0">${g[1]}</p></div>`).join('')}</div><div class="empty" id="glE" hidden><h3>No matching terms</h3><a class="btn btn-o" href="/contact/">Ask our team</a></div>`);

