/* ============ V8: page enrichment + search, profiles, saved, map, loading guide ============ */
function hashStr(s){let h=0;for(const c of s)h=(h*31+c.charCodeAt(0))>>>0;return h}
const GALLERY_KEYS=['truckRoad','uhaul','unload1','unload2','carry','yellowTruck','boxesRoom','womanBoxes','couple','boxesWindow','boxesTable','stacked','packWh','boxesRoad','wh1','wh2','wh3','forklift','house1','house2','house3','house4','house5','house6','loadTruck','semi','boxes2','boxPile','boxesOpen','redTruck','mtnTruck','mattress','sideboard','chairs'];
const GALLERY_ALT={truckRoad:'Moving truck on the highway',uhaul:'Rental moving truck parked',unload1:'Movers unloading furniture',unload2:'Moving crew carrying a sofa',carry:'Mover carrying boxes',yellowTruck:'Box truck ready to load',boxesRoom:'Packed boxes in an empty room',womanBoxes:'Woman packing moving boxes',couple:'Couple packing for a move',boxesWindow:'Boxes stacked by a window',boxesTable:'Labelled moving boxes on a table',stacked:'Stacked cardboard boxes',packWh:'Packing materials in a warehouse',boxesRoad:'Boxes ready for transport',wh1:'Storage warehouse aisle',wh2:'Warehouse with pallets',wh3:'Logistics warehouse',forklift:'Forklift moving pallets',house1:'Family home exterior',house2:'Suburban house',house3:'House with front yard',house4:'Modern home',house5:'Bright living room',house6:'Empty room ready for furniture',loadTruck:'Loading a moving truck',semi:'Long-haul semi truck',boxes2:'Moving boxes and tape',boxPile:'Pile of moving boxes',boxesOpen:'Open boxes being packed',redTruck:'Red moving truck',mtnTruck:'Truck on a mountain road',mattress:'Mattress wrapped for moving',sideboard:'Furniture wrapped for protection',chairs:'Chairs prepared for moving'};
const gallery=(seed,n=3,skip=[])=>{const ks=GALLERY_KEYS.filter(k=>!skip.includes(k));let h=hashStr(seed);const out=[];while(out.length<n){const k=ks[h%ks.length];if(!out.includes(k))out.push(k);h=(h*7+13)>>>0}return out};
const galBlock=(seed,h,p,skip)=>`<section class="enr"><div class="wrap"><div class="sh"><h2>${h}</h2><p>${p}</p></div><div class="gal">${gallery(seed,3,skip).map(k=>`<figure class="rv-in">${img(k,GALLERY_ALT[k],700)}<figcaption>${GALLERY_ALT[k]}</figcaption></figure>`).join('')}</div></div></section>`;
const TOOLS=[['Moving Cost Calculator','/tools/moving-cost-calculator/','calc','Indicative price range'],['Volume Calculator','/tools/volume-calculator/','box','Cubic feet & truck size'],['Box Calculator','/tools/moving-box-calculator/','box','Boxes by type'],['Packing Calculator','/tools/packing-calculator/','box','Supplies list'],['Storage Calculator','/tools/storage-calculator/','building','Unit size'],['Budget Planner','/tools/moving-budget-planner/','calc','Plan your spend'],['Date Planner','/tools/moving-date-planner/','cal','Cheaper dates'],['Route Planner','/tools/moving-route-planner/','map','Distance & drive time'],['Moving Checklist','/tools/moving-checklist/','list','Week-by-week tasks'],['Room Planner','/room-planner/','home','Furniture & doorways'],['Box Labels','/box-labels/','doc','Printable labels'],['My Moving Space','/my-move/','spark','Your whole plan']];
const GUIDES=[['Understanding Moving Estimates','/learn/estimates/'],['Moving Protection & Valuation','/learn/protection/'],['Moving Fraud Awareness','/learn/scams/'],['Mover Credentials Explained','/learn/credentials/'],['Interstate Moving Rules','/learn/interstate-rules/'],['Preparing a Moving Claim','/learn/claims-prep/'],['How MoveMatch Compares','/learn/how-we-compare/'],['Moving With Pets','/learn/pets/'],['Shipping a Vehicle','/learn/vehicles/'],['Seasonal Moving Guide','/learn/seasons/'],['Moving Glossary','/learn/glossary/']];
const toolsBlock=(p,h='Planning tools that work together')=>{const list=TOOLS.filter(t=>t[1]!==p);const s=hashStr(p)%list.length;const pick=[...list.slice(s),...list.slice(0,s)].slice(0,4);return`<section class="enr"><div class="wrap"><div class="sh"><h2>${h}</h2><p>Free calculators and planners — no sign-up needed, and your entries stay in your browser.</p></div><div class="grid g4">${pick.map(t=>`<a class="card tcard hov rv-in" href="${t[1]}"><span class="ib">${ic(t[2],22)}</span><b>${t[0]}</b><small>${t[3]}</small></a>`).join('')}</div></div></section>`};
const guidesBlock=(p,h='Guides worth reading first')=>{const list=GUIDES.filter(g=>g[1]!==p);const s=hashStr(p+'g')%list.length;const pick=[...list.slice(s),...list.slice(0,s)].slice(0,3);return`<section class="enr alt"><div class="wrap"><div class="sh"><h2>${h}</h2><p>Plain-English explanations from the MoveMatch Learning Center.</p></div><div class="grid g3">${pick.map(g=>`<a class="card hov rv-in" href="${g[1]}"><small class="help">${ic('doc',14)} Guide</small><h3 style="font-size:18px;margin:6px 0">${g[0]}</h3><span class="link">Read guide ${arr}</span></a>`).join('')}</div></div></section>`};
const trustBlock=()=>`<section class="enr"><div class="wrap split"><div class="pframe rv-in">${img('carry','Mover carrying boxes to a truck',900)}</div><div><h2>How MoveMatch keeps comparisons honest</h2><ul class="ticks"><li>Every verification check is shown separately — identity, business, licence, insurance</li><li>Sponsored placements are always labelled and never change rankings</li><li>Only customers with a completed booking can leave a verified review</li><li>Estimates show their type: binding, non-binding or not-to-exceed</li></ul><a class="btn btn-o" href="/learn/how-we-compare/">Read our methodology</a></div></div></section>`;
const qBlock=(label)=>`<section class="enr alt"><div class="wrap split"><div><h2>Questions to ask any ${label} mover</h2><ol class="tl-v">${['Is the estimate binding, non-binding or not-to-exceed?','What is your USDOT number (for interstate moves)?','Which protection options do you offer, and what does each cost?','Are stairs, long carries or elevators charged extra?','Who will actually do the move — your crew or a partner carrier?','What is the delivery window, and how will I be updated?'].map((q,i)=>`<li><i>${i+1}</i><div><b>${q}</b></div></li>`).join('')}</ol></div><div class="card" style="align-self:start"><h3>Red flags to watch for</h3><ul class="ticks x">${['A large cash deposit up front','No written estimate','Estimate without seeing or listing your items','Blank or incomplete paperwork to sign','A price far below every other quote'].map(x=>`<li>${x}</li>`).join('')}</ul><a class="link" href="/learn/scams/">Take the scam self-check ${arr}</a></div></div></section>`;
const costBlock=(label)=>`<section class="enr"><div class="wrap"><div class="sh"><h2>What affects the cost of ${label} moves</h2><p>No two moves cost the same. These factors move the price the most.</p></div><div class="grid g3">${[['ruler','Volume & weight','How much you move drives crew size, truck size and time.'],['map','Distance','Local moves are usually hourly; long-distance moves are priced by weight or volume.'],['cal','Date & season','May–September and month-ends are busiest and usually cost more.'],['building','Access','Stairs, elevators, long walks and parking permits add time.'],['box','Packing services','Full packing can add significantly; partial packing is a middle ground.'],['shield','Protection level','Full value protection costs more than basic released value.']].map(x=>`<div class="card rv-in"><span class="ib">${ic(x[0],22)}</span><h3 style="font-size:17px;margin:10px 0 4px">${x[1]}</h3><p class="help" style="margin:0">${x[2]}</p></div>`).join('')}</div><p style="margin-top:16px"><a class="btn btn-o" href="/tools/moving-cost-calculator/">Estimate my move cost</a></p></div></section>`;
const TOOLINFO={
 'moving-cost-calculator':['Combines home size, distance and services into an indicative range based on typical industry pricing patterns.',['Choose the home size that matches what you are actually moving, not the home size','Add packing only if you want the crew to pack','Compare the range with at least three written estimates']],
 'volume-calculator':['Adds standard cubic-foot allowances for each item you list and suggests a truck size with some spare room.',['Count large furniture first — it dominates the total','Add 10–15% for odd shapes and boxes you forgot','Garage and outdoor items are easy to miss']],
 'moving-box-calculator':['Uses typical box counts per room type and adjusts for how full your home is.',['Use small boxes for books — they get heavy fast','Wardrobe boxes save hours on hanging clothes','Buy a few extra; unused boxes are often returnable']],
 'packing-calculator':['Turns your box estimate into a supplies list: tape, paper, bubble wrap and markers.',['One roll of tape seals about 15–20 boxes','Packing paper is cheaper than bubble wrap for dishes','Keep a "first night" box separate and labelled']],
 'storage-calculator':['Matches the volume of your items to common storage unit sizes.',['Leave a walkway so you can reach items later','Climate control matters for wood, electronics and photos','Stand mattresses and sofas upright to save floor space']],
 'moving-budget-planner':['Totals planned costs by category and shows what is left of your budget.',['Include deposits for the new home and utilities','Set aside 10% for surprises','Tip money for crews is often forgotten']],
 'moving-date-planner':['Rates dates by typical seasonal demand, weekday and month-end patterns.',['Mid-month weekdays are often cheaper','Avoid the last weekend of the month if you can','Book 4–8 weeks ahead in summer']],
 'moving-route-planner':['Estimates driving distance and time between two places to help plan travel days.',['Plan about 400–500 miles of driving per day','Check truck height limits on parkways','Book overnight stops ahead in peak season']],
 'moving-checklist':['Organises the common moving tasks into a week-by-week plan you can tick off.',['Start eight weeks out for long-distance moves','Change your address with USPS about two weeks before','Confirm your mover 48 hours ahead']],
 'moving-estimate-calculator':['Gives a rough estimate from a quick description of your move.',['Use it to sanity-check quotes, not replace them','Ask movers what is excluded','Make sure every quote covers the same items']]};
const toolExtras=slug=>{const t=TOOLINFO[slug];if(!t)return'';return`<section class="enr alt"><div class="wrap split"><div><h2>How this tool works</h2><p>${t[0]}</p><p class="help">Results are estimates for planning only. Real prices come from written quotes.</p></div><div class="card"><h3>Tips for a more accurate result</h3><ul class="ticks">${t[1].map(x=>`<li>${x}</li>`).join('')}</ul></div></div></section>`};

const TOOLFAQ={
 'moving-cost-calculator':[['How accurate is the estimate?','It shows a typical range only. Written quotes based on your inventory are the real price.'],['Why is long-distance priced differently?','Interstate moves are usually priced by weight or volume and distance, not hours.'],['Does it include packing?','Only if you tick packing services — packing can add a significant amount.']],
 'volume-calculator':[['What is a cubic foot?','A cube one foot on each side. Movers use it to size trucks and price some moves.'],['Should I round up?','Yes — add 10–15% for awkward shapes and forgotten items.'],['Does weight matter too?','For long-distance moves weight often sets the price; volume helps estimate it.']],
 'moving-box-calculator':[['Which box size is most useful?','Medium boxes suit most household items; small boxes are best for books.'],['Can I use free boxes?','Yes if they are clean, dry and sturdy. Avoid produce boxes.'],['How do I label boxes?','Room, contents and "this side up". Try our printable box labels.']],
 'packing-calculator':[['How much tape do I need?','Roughly one roll per 15–20 boxes, sealing top and bottom.'],['Paper or bubble wrap?','Paper for most dishes and decor; bubble wrap for electronics and glass.'],['When should I start packing?','Two to three weeks ahead for a typical home, starting with rooms you use least.']],
 'storage-calculator':[['Do I need climate control?','For wood furniture, electronics, documents and photos it is strongly recommended.'],['Can movers deliver to storage?','Many offer storage or delivery to a unit — ask when requesting quotes.'],['How is storage priced?','Usually monthly, by unit size and location.']],
 'moving-budget-planner':[['What do people forget to budget?','Deposits, utility setup fees, tips, travel and the first grocery shop.'],['How big should my buffer be?','Around 10% of the total is a sensible starting point.'],['Are moving costs tax deductible?','Rules changed in recent years and mostly apply to active-duty military — check with a tax professional.']],
 'moving-date-planner':[['Which days are cheapest?','Typically mid-month weekdays outside the summer peak.'],['How far ahead should I book?','4–8 weeks in summer; 2–4 weeks is often enough in winter.'],['Is moving in winter a good idea?','Prices and availability are often better, but plan for weather.']],
 'moving-route-planner':[['How far can I drive a truck in a day?','Around 400–500 miles is comfortable for most drivers.'],['Are there routes trucks should avoid?','Some parkways ban trucks and some bridges have height limits.'],['Should I plan rest stops?','Yes — every two hours or so, and book overnight stops ahead.']],
 'moving-checklist':[['When should I start?','About eight weeks out for a long-distance move, four for a local one.'],['What is the most forgotten task?','Changing your address with banks, insurers and subscriptions.'],['Can I save my progress?','Yes — use My Moving Space to keep checklists on this device.']],
 'moving-estimate-calculator':[['Is this the same as a quote?','No. It is a planning estimate; providers give binding or non-binding quotes.'],['Why do quotes vary so much?','Different inventories, services and estimate types — compare like for like.'],['What if the final bill is higher?','Read the estimate type; binding estimates protect you from increases.']]};
const faqSec=(list,h='Frequently asked questions')=>`<section class="enr alt"><div class="wrap" style="max-width:860px"><div class="sh"><h2>${h}</h2><p>Short answers to the questions people ask most.</p></div>${faqBlock(list)}</div></section>`;
const nextSteps=()=>`<section class="enr"><div class="wrap"><div class="sh"><h2>From estimate to booked move</h2><p>Turn your planning into real, comparable quotes in four steps.</p></div><div class="grid g4">${[['Plan','Use the tools to size your move and set a budget.'],['Request','Send one request to multiple providers.'],['Compare','Check estimate types, inclusions and verification.'],['Book','Confirm your date and keep everything in My Moving Space.']].map((x,i)=>`<div class="card rv-in"><span class="ib">${i+1}</span><h3 style="font-size:17px;margin:10px 0 4px">${x[0]}</h3><p class="help" style="margin:0">${x[1]}</p></div>`).join('')}</div><p style="margin-top:16px"><a class="btn btn-p" href="/get-quotes/">Get free quotes</a></p></div></section>`;
const mistakesBlock=()=>`<section class="enr"><div class="wrap split"><div class="pframe rv-in">${img('boxPile','Pile of moving boxes',900)}</div><div><h2>Common moving mistakes to avoid</h2><ul class="ticks x"><li>Booking the cheapest quote without checking what is included</li><li>Starting to pack too late</li><li>Forgetting to reserve elevators or parking</li><li>Packing important documents in the truck</li><li>Not measuring large furniture and doorways</li></ul><a class="link" href="/room-planner/">Check your furniture fits ${arr}</a></div></div></section>`;
const EXCLUDE=/^\/(404|admin|dashboard|company-os|partner-os|operations-os|super-admin|login|signup|enterprise\/portal|pricing-studio|legal|search|developer)\//;
function enrich(p,title){
 if(p==='/'||EXCLUDE.test(p))return'';
 let o='';
 if(p.startsWith('/tools/')){const slug=p.split('/')[2];o=toolExtras(slug)+mistakesBlock()+galBlock(p,'Plan with confidence','Good planning makes moving day calmer and cheaper.')+nextSteps()+(TOOLFAQ[slug]?faqSec(TOOLFAQ[slug]):'')+guidesBlock(p)+toolsBlock(p,'More free planning tools')}
 else if(p.startsWith('/movers/')&&!p.startsWith('/movers/profile/')){const label=title.replace(/ ?Movers?.*/i,'').toLowerCase()||'local';o=qBlock(label)+costBlock(label)+galBlock(p,`Real ${label} moving, done right`,'Professional crews, protected furniture and careful loading.')+trustBlock()+toolsBlock(p)+guidesBlock(p)}
 else if(p.startsWith('/services/')){o=galBlock(p,'In action','What a professionally handled move looks like.')+guidesBlock(p)+toolsBlock(p)}
 else if(p.startsWith('/learn/')){o=galBlock(p,'From planning to delivery','Moments where this knowledge matters most.')+trustBlock()+nextSteps()+toolsBlock(p,'Put it into practice')+(p==='/learn/'?'':guidesBlock(p,'Keep learning'))}
 else if(p.startsWith('/movers/profile/'))o='';
 else o=galBlock(p,'Moving made manageable','A good plan, the right crew and clear paperwork.')+nextSteps()+mistakesBlock()+trustBlock()+toolsBlock(p)+guidesBlock(p);
 return o;}

/* --- Provider profiles (sample, clearly labelled) --- */
const slugify=s=>s.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
PROV.forEach((pv,idx)=>{const p=`/movers/profile/${slugify(pv.n)}/`;const others=PROV.filter(x=>x!==pv&&x.cat.some(c=>pv.cat.includes(c))).concat(PROV.filter(x=>x!==pv)).filter((x,i,a)=>a.indexOf(x)===i).slice(0,3);
 page(p,{title:`${pv.n} — Sample Provider Profile`,desc:`Sample MoveMatch provider profile for ${pv.n}: services, service area, verification checks and quote options.`,noindex:1,cr:[['Find Movers','/movers/search/'],[pv.n,p]],
 body:`<section class="phero">${img(pv.im,'',1600,true).replace('<img','<img class="bg"')}<div class="wrap">${crumbs([['Find Movers','/movers/search/'],[pv.n]])}<span class="sample">Sample profile — not a real company</span><div style="display:flex;gap:16px;align-items:center;margin-top:12px"><div class="plogo" style="position:static;width:64px;height:64px;font-size:22px">${pv.i}</div><h1 class="st st1" style="margin:0">${pv.n}</h1></div><p class="lead st st2">${pv.type} · ${pv.area}</p><div class="ctas st st3"><a class="btn btn-p btn-lg" href="/get-quotes/" data-seed='{"provider":"${pv.n}"}'>Request a quote ${arr}</a><button class="btn btn-w btn-lg" type="button" data-save="${pv.id}" aria-pressed="false">♡ Save</button></div></div></section>
<section><div class="wrap"><div class="notice">${ic('help',20)}<div>This is a <b>sample profile</b> showing how provider pages will look. Real providers appear only after they pass review. No ratings, availability or reviews are invented.</div></div></div></section>
<section class="enr"><div class="wrap split"><div><h2>About this provider</h2><dl class="kv"><dt>Provider type</dt><dd>${pv.type}</dd><dt>Services</dt><dd>${pv.svc}</dd><dt>Estimate style</dt><dd>${pv.est}</dd><dt>Categories</dt><dd>${pv.cat.join(', ')}</dd></dl></div><div class="card"><h3>Verification checks</h3>${['Identity','Business','USDOT/MC','Insurance'].map(c=>`<div class="vrow"><span>${c}</span><b class="${pv.ch.includes(c)?'ok':'na'}">${pv.ch.includes(c)?'✓ Completed':'Not completed'}</b></div>`).join('')}<a class="link" href="/learn/credentials/">What each check means ${arr}</a></div></div></section>
<section class="enr alt"><div class="wrap"><div class="sh"><h2>Service area</h2><p>${pv.area}. Exact coverage is confirmed when a provider responds to your request.</p></div><div class="card" style="display:flex;gap:16px;align-items:center;flex-wrap:wrap"><span class="ib">${ic('map',22)}</span><div style="flex:1;min-width:200px"><b>${pv.area}</b><p class="help" style="margin:0">Enter your ZIP codes in the quote form to check coverage.</p></div><a class="btn btn-o" href="/moving-map/">Explore the US moving map</a></div></div></section>
${galBlock(p,'Photo gallery','Illustrative stock photography — real providers upload their own photos.',[pv.im])}
<section class="enr"><div class="wrap"><div class="sh"><h2>Ratings & reviews</h2><p>Only customers with a completed booking can leave a verified review.</p></div><div class="empty"><h3>No verified reviews yet</h3><p class="help">We never show invented ratings.</p><a class="btn btn-o" href="/learn/how-we-compare/">How reviews work</a></div></div></section>
<section class="enr alt"><div class="wrap"><div class="sh"><h2>Similar providers</h2><p>Other sample profiles offering related services.</p></div><div class="grid g3">${others.map((o,i)=>provCard(o,i)).join('')}</div></div></section>${ctaBlock()}`})});

