page('/search/',{title:'Search MoveMatch',desc:'Search every MoveMatch page, service, tool and guide.',noindex:1,cr:[['Search','/search/']],body:phero([['Search']],'Site search','Search MoveMatch','Find services, movers, tools and guides. Tip: press Ctrl + K on any page.','boxesWindow')+`<section><div class="wrap" style="max-width:860px"><form id="srF" role="search" class="fld" style="margin-bottom:18px"><label for="srQ">Search</label><div class="iw">${ic('search',18)}<input id="srQ" type="search" placeholder="e.g. piano, storage, interstate" autocomplete="off"></div></form><div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px" id="srCat" role="group" aria-label="Filter results">${['All','Services','Movers','Tools','Guides','Company'].map((c,i)=>`<button class="chipb" type="button" aria-pressed="${!i}" data-k="${c}">${c}</button>`).join('')}</div><p class="help" id="srN" aria-live="polite"></p><div id="srR"></div><div class="empty" id="srE" hidden><h3>No results</h3><p class="help">Try a different word, or browse popular pages.</p><div style="display:flex;gap:8px;justify-content:center;flex-wrap:wrap"><a class="btn btn-o" href="/services/residential-moving/">Services</a><a class="btn btn-o" href="/tools/moving-cost-calculator/">Tools</a><a class="btn btn-o" href="/learn/">Guides</a><a class="btn btn-p" href="/get-quotes/">Get quotes</a></div></div></div></section>`});

