page('/saved/',{title:'Saved Movers & Plans',desc:'Providers you saved and recently viewed, plus your saved moving plan — stored on this device.',noindex:1,cr:[['Saved','/saved/']],body:phero([['Saved']],'Your shortlist','Saved movers & plans','Saved on this device only. Sign-in sync will arrive with customer accounts.','couple')+`<section><div class="wrap"><h2 class="sa-h">Saved providers</h2><div class="grid g3" id="svList"></div><div class="empty" id="svE" hidden><h3>Nothing saved yet</h3><p class="help">Tap ♡ Save on any provider profile.</p><a class="btn btn-p" href="/movers/search/">Browse movers</a></div></div></section><section class="enr alt"><div class="wrap"><h2 class="sa-h">Recently viewed providers</h2><div class="grid g3" id="rvList"></div><p class="help" id="rvE" hidden>No providers viewed yet.</p></div></section><section class="enr"><div class="wrap split"><div><h2>Your moving plan</h2><p id="svPlan" class="help">Open My Moving Space to create a plan.</p><a class="btn btn-o" href="/my-move/">Open My Moving Space</a></div><div><h2>Recently visited pages</h2><div id="rvPages"></div></div></div></section>
<script type="application/json" id="provData">${JSON.stringify(PROV.map(x=>({id:x.id,n:x.n,i:x.i,area:x.area,svc:x.svc,u:`/movers/profile/${slugify(x.n)}/`})))}</script>`});

