page('/notifications/',{title:'Notifications & Reminders',desc:'Moving reminders built from your plan, and where account notifications will appear.',noindex:1,cr:[['Notifications','/notifications/']],body:phero([['Notifications']],'Stay on track','Notifications & reminders','Reminders below come from the moving date you set in My Moving Space.','boxesTable')+`<section><div class="wrap" style="max-width:860px"><div class="tabs" role="tablist" aria-label="Notifications"><button class="tab" role="tab" id="nt0" aria-selected="true" aria-controls="np0">Reminders</button><button class="tab" role="tab" id="nt1" aria-selected="false" aria-controls="np1" tabindex="-1">Account updates</button></div><div role="tabpanel" id="np0" aria-labelledby="nt0"><div id="ntList"></div></div><div role="tabpanel" id="np1" aria-labelledby="nt1" hidden><div class="empty"><h3>Account notifications aren't available yet</h3><p class="help">Quote responses, booking updates and messages will appear here once customer accounts are connected to the booking system.</p><a class="btn btn-o" href="/get-quotes/">Request quotes</a></div></div></div></section>`});

