page('/feedback/',{title:'Share Feedback',desc:'Tell the MoveMatch team what works and what we should improve.',cr:[['Feedback','/feedback/']],body:phero([['Feedback']],'Help us improve','Share your feedback','Every message is read by the MoveMatch team.','womanBoxes')+`<section><div class="wrap split" style="align-items:start"><form class="card" id="fbF" novalidate><fieldset style="border:0;padding:0;margin:0 0 14px"><legend style="font-weight:700;margin-bottom:8px">How was your experience?</legend><div style="display:flex;gap:8px;flex-wrap:wrap">${['Very poor','Poor','Okay','Good','Excellent'].map((r,i)=>`<label class="chipb"><input type="radio" name="fbR" value="${i+1}" class="sr">${r}</label>`).join('')}</div></fieldset><div class="fld"><label for="fbT">Topic</label><select id="fbT"><option>Website</option><option>Getting quotes</option><option>Tools & calculators</option><option>Guides</option><option>Something else</option></select></div><div class="fld"><label for="fbM">Your feedback</label><textarea id="fbM" rows="5" required style="width:100%;border:1.5px solid var(--n3);border-radius:10px;padding:12px;font:inherit"></textarea><div class="msg">Please write a few words.</div></div><div class="fld"><label for="fbE">Email (optional, for a reply)</label><input id="fbE" type="email"></div><button class="btn btn-p full">Send feedback</button><p class="help" style="margin-top:10px">Opens your email app with the message ready to send to the MoveMatch team.</p></form><div><h2>What happens next</h2><ol class="tl-v"><li><i>1</i><div><b>We read it</b><span>Feedback goes to the product team.</span></div></li><li><i>2</i><div><b>We prioritise</b><span>Common requests shape the roadmap.</span></div></li><li><i>3</i><div><b>We reply</b><span>If you leave an email and ask a question.</span></div></li></ol><p><a class="link" href="/help-center/">Need help instead? Visit the Help Center ${arr}</a></p></div></div></section>`});

/* --- Truck loading guide --- */
const TRUCKS=[['10 ft','Studio / 1 room','~400 cu ft'],['15 ft','1–2 bedrooms','~760 cu ft'],['20 ft','2–3 bedrooms','~1,000 cu ft'],['26 ft','3–5 bedrooms','~1,700 cu ft']];
page('/truck-loading-guide/',{title:'How to Load a Moving Truck',desc:'Step-by-step visual guide to loading a moving truck safely, plus truck sizes by home size.',cr:[['Guides','/moving-guides/'],['Truck Loading Guide','/truck-loading-guide/']],body:phero([['Guides','/moving-guides/'],['Truck Loading Guide']],'Visual guide','How to load a moving truck','Load in tiers, heavy to light, and nothing shifts on the road.','loadTruck')+`<section><div class="wrap"><div class="sh"><h2>The loading order</h2><p>Click a zone to see what goes there.</p></div><div class="card"><svg viewBox="0 0 600 220" role="img" aria-label="Truck loading zones diagram" style="width:100%;height:auto"><rect x="10" y="30" width="470" height="160" rx="8" fill="#F0F4F8" stroke="#102A43" stroke-width="3"/><rect x="480" y="80" width="100" height="110" rx="10" fill="#102A43"/><rect x="500" y="95" width="55" height="40" rx="4" fill="#D9E2EC"/><circle cx="110" cy="200" r="18" fill="#334E68"/><circle cx="420" cy="200" r="18" fill="#334E68"/><circle cx="530" cy="200" r="18" fill="#334E68"/>${[['1','Heavy','#14B8A6',360],['2','Long','#5EEAD4',250],['3','Boxes','#F4B740',140],['4','Last','#FDE68A',30]].map((z,i)=>`<g class="lz" data-z="${i}" tabindex="0" role="button" aria-label="Zone ${z[0]}: ${z[1]}" style="cursor:pointer"><rect x="${z[3]+8}" y="40" width="100" height="140" rx="6" fill="${z[2]}"/><text x="${z[3]+58}" y="105" text-anchor="middle" font-weight="800" font-size="26" fill="#102A43">${z[0]}</text><text x="${z[3]+58}" y="130" text-anchor="middle" font-size="13" fill="#102A43">${z[1]}</text></g>`).join('')}<text x="20" y="22" font-size="12" fill="#52606D">Rear door</text><text x="400" y="22" font-size="12" fill="#52606D">Cab end</text></svg><div id="lzOut" class="notice" style="margin-top:12px" aria-live="polite">Select a zone.</div></div></div></section>
<section class="enr alt"><div class="wrap"><div class="sh"><h2>Which truck size do you need?</h2><p>Typical capacities. Rental fleets vary, so check the exact model.</p></div><div class="grid g4">${TRUCKS.map(t=>`<div class="card rv-in" style="text-align:center"><span class="ib" style="margin:auto">${ic('truck',22)}</span><h3 style="margin:10px 0 2px">${t[0]}</h3><b style="color:var(--teal2)">${t[1]}</b><p class="help">${t[2]}</p></div>`).join('')}</div><p><a class="btn btn-o" href="/tools/volume-calculator/">Calculate my volume</a> <a class="btn btn-g" href="/truck-rental/">Compare truck rental</a></p></div></section>
<section class="enr"><div class="wrap split"><div><h2>Safety essentials</h2><ul class="ticks"><li>Use a dolly and lift with your legs</li><li>Tie off every tier with straps to the rails</li><li>Keep weight balanced left to right</li><li>Never load flammables, propane or paint</li><li>Fill gaps with soft items so nothing slides</li></ul></div><div class="pframe">${img('loadTruck','Loading boxes into a truck',900)}</div></div></section>`});

