const STN={AK:'Alaska',AL:'Alabama',AR:'Arkansas',AZ:'Arizona',CA:'California',CO:'Colorado',CT:'Connecticut',DC:'District of Columbia',DE:'Delaware',FL:'Florida',GA:'Georgia',HI:'Hawaii',IA:'Iowa',ID:'Idaho',IL:'Illinois',IN:'Indiana',KS:'Kansas',KY:'Kentucky',LA:'Louisiana',MA:'Massachusetts',MD:'Maryland',ME:'Maine',MI:'Michigan',MN:'Minnesota',MO:'Missouri',MS:'Mississippi',MT:'Montana',NC:'North Carolina',ND:'North Dakota',NE:'Nebraska',NH:'New Hampshire',NJ:'New Jersey',NM:'New Mexico',NV:'Nevada',NY:'New York',OH:'Ohio',OK:'Oklahoma',OR:'Oregon',PA:'Pennsylvania',RI:'Rhode Island',SC:'South Carolina',SD:'South Dakota',TN:'Tennessee',TX:'Texas',UT:'Utah',VA:'Virginia',VT:'Vermont',WA:'Washington',WI:'Wisconsin',WV:'West Virginia',WY:'Wyoming'};
page('/moving-map/',{title:'US Moving Map',desc:'Interactive map of the United States: pick an origin and destination state to plan an interstate move.',cr:[['Guides','/moving-guides/'],['US Moving Map','/moving-map/']],body:phero([['Guides','/moving-guides/'],['US Moving Map']],'Interactive map','US moving map','Pick where you are moving from, then where you are moving to.','mtnTruck')+`<section><div class="wrap"><div class="calc" style="grid-template-columns:1fr 320px;align-items:start"><div class="card"><div class="usmap" role="group" aria-label="US states">${ST.map(s=>`<button type="button" class="stt" data-s="${s[0]}" style="grid-row:${s[1]+1};grid-column:${s[2]+1}" aria-label="${STN[s[0]]}">${s[0]}</button>`).join('')}</div><p class="help">Tile map — each state is shown as an equal square for easy selection.</p></div><div class="res"><h3>Your route</h3><div class="rows"><div><span>From</span><b id="umF">Select a state</b></div><div><span>To</span><b id="umT">—</b></div><div><span>Move type</span><b id="umK">—</b></div></div><a class="btn btn-p" id="umGo" href="/get-quotes/" style="width:100%;margin-top:12px">Get quotes for this route</a><button class="btn btn-g" id="umR" type="button" style="width:100%;margin-top:8px">Reset</button></div></div></div></section>
<section class="enr alt"><div class="wrap"><div class="sh"><h2>Interstate or intrastate?</h2><p>Crossing a state line changes the rules that protect you.</p></div><div class="grid g2"><div class="card"><h3>Interstate moves</h3><p class="help">Regulated by the FMCSA. Carriers need a USDOT number, and you should receive the "Your Rights and Responsibilities" booklet.</p><a class="link" href="/learn/interstate-rules/">Interstate rules ${arr}</a></div><div class="card"><h3>Within one state</h3><p class="help">Rules are set by each state; some require a state licence.</p><a class="link" href="/state-guides/">State guides ${arr}</a></div></div></div></section>`});

page('/404/',{title:'Page not found',desc:'This page could not be found.',noindex:1,body:`<section style="text-align:center"><div class="wrap"><p class="eyebrow">Error 404</p><h1 class="h2" style="font-size:48px">This page took a wrong turn.</h1><p class="lead" style="margin:0 auto 24px">The page you're looking for doesn't exist or has moved.</p><div style="display:flex;gap:12px;justify-content:center;flex-wrap:wrap"><a class="btn btn-p" href="/">Go home</a><a class="btn btn-o" href="/get-quotes/">Get quotes</a></div></div></section>`});

/* ===== V9: PRD 02–06 & 08 dashboards (os.js engine) ===== */
const OSP=[['/dashboard/','customer','Customer Dashboard','PRD 02 — quotes, bookings, inventory, payments, claims and documents for your move.'],
['/company-os/','company','Moving Company OS','PRD 03 — leads, quotes, dispatch, crews, fleet, storage and finance for moving companies.'],
['/partner-os/','partner','PartnerOS','PRD 04 — onboarding, verification, services, quotations, jobs and settlements for service partners.'],
['/operations-os/','ops','Operations OS','PRD 05 — workforce, dispatch, fleet, warehouse, chain of custody and field execution.'],
['/enterprise/portal/','enterprise','Enterprise OS','PRD 06 — relocation cases, approvals, budgets, invoices and vendors for employers.'],
['/developer/portal/','developer','Developer Portal','PRD 08 — applications, API keys, sandbox explorer and signed webhooks.']];
OSP.forEach(([p,id,t,d])=>{const i=QUEUE.findIndex(q=>q[0]===p);const o={title:t,desc:d,noindex:1,cr:[[t,p]],body:`<div class="sa os" id="os" data-os="${id}"><noscript><div class="wrap" style="padding:40px">This dashboard needs JavaScript.</div></noscript></div><script src="/os-config.js?v=${V}" defer></script><script src="/os.js?v=${V}" defer></script>`};if(i>=0)QUEUE[i]=[p,o];else page(p,o)});
page('/platform/dashboards/',{title:'All MoveMatch Dashboards',desc:'Open the interactive demos of every MoveMatch dashboard — customer, company, partner, operations, enterprise, developer and super admin.',cr:[['Platform','/platform/'],['Dashboards','/platform/dashboards/']],body:phero([['Platform','/platform/'],['Dashboards']],'Eight connected interfaces','Every MoveMatch dashboard','Interactive demos built from PRDs 01–08. Admin sign-in required · sample data only.','office2')+`<section><div class="wrap"><div class="grid g3">${[...OSP.map(x=>[x[2],x[0],x[3]]),['Public Website & Marketplace','/','PRD 07 — the public site you are on: search, services, movers, tools and guides.'],['Super Admin Panel','/super-admin/','PRD 01 — password-protected founder control tower.']].map(x=>`<a class="card hov rv-in" href="${x[1]}"><h3 style="font-size:19px">${x[0]}</h3><p class="help">${x[2]}</p><span class="link">Open ${arr}</span></a>`).join('')}</div></div></section>`});
QUEUE.forEach(([p,o])=>renderPage(p,o));
fs.writeFileSync(path.join(OUT,'search-index.json'),JSON.stringify(SEARCH));
fs.copyFileSync(path.join(OUT,'404','index.html'),path.join(OUT,'404.html'));

