for(const f of['favicon-16.png','favicon-32.png','apple-touch-icon.png','icon-192.png','icon-512.png','og-image.png'])if(fs.existsSync(path.join(__dirname,f)))fs.copyFileSync(path.join(__dirname,f),path.join(OUT,f));
const fav=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="14" fill="#102A43"/><g fill="none" stroke="#14B8A6" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"><path d="M10 42V18h26v24M36 26h9l9 9v7H36"/></g><circle cx="19" cy="45" r="5" fill="#F4B740"/><circle cx="45" cy="45" r="5" fill="#F4B740"/></svg>`;
fs.writeFileSync(path.join(OUT,'favicon.svg'),fav);
