fs.writeFileSync(path.join(OUT,'site.webmanifest'),JSON.stringify({name:'MoveMatch',short_name:'MoveMatch',start_url:'/',display:'standalone',background_color:'#FFFFFF',theme_color:'#102A43',icons:[{src:'/icon-192.png',sizes:'192x192',type:'image/png'},{src:'/icon-512.png',sizes:'512x512',type:'image/png'},{src:'/favicon.svg',sizes:'any',type:'image/svg+xml'}]},null,1));
fs.writeFileSync(path.join(OUT,'robots.txt'),`User-agent: *\nAllow: /\nDisallow: /login/\nDisallow: /signup/\nDisallow: /super-admin/\nDisallow: /admin-login\nSitemap: ${SITE}/sitemap.xml\n`);
fs.writeFileSync(path.join(OUT,'sitemap.xml'),`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${PAGES.filter(p=>!['/404/','/login/','/signup/','/super-admin/'].includes(p)).map(p=>`<url><loc>${SITE}${p}</loc></url>`).join('\n')}\n</urlset>`);
