fs.writeFileSync(path.join(OUT,'IMAGE-CREDITS.md'),`# Image credits\nAll photographs are from Unsplash (https://unsplash.com) under the Unsplash License (free for commercial use, no attribution required). Served from images.unsplash.com.\n\n${Object.entries(IMG).map(([k,v])=>`- ${k}: https://images.unsplash.com/photo-${v}`).join('\n')}\n`);
